def friendly_tg_error(e) -> str:
    """Превращает сырые ошибки Telegram API в понятный русский текст."""
    raw = str(e).lower()
    mapping = [
        ("user is an administrator of the chat", "❌ Нельзя применить действие: пользователь — администратор этого чата."),
        ("chat_admin_required", "❌ У бота недостаточно прав администратора для этого действия."),
        ("not enough rights", "❌ У бота недостаточно прав администратора для этого действия."),
        ("can't remove chat owner", "❌ Нельзя применить действие к владельцу чата."),
        ("user not found", "❌ Пользователь не найден в этом чате."),
        ("chat not found", "❌ Чат не найден. Проверьте, что бот добавлен в него."),
        ("user_id_invalid", "❌ Некорректный пользователь."),
        ("message to delete not found", "❌ Сообщение уже удалено."),
        ("message can't be deleted", "❌ Не удалось удалить сообщение — прошло слишком много времени."),
        ("bot was blocked", "❌ Бот заблокирован пользователем — не удалось отправить сообщение."),
        ("forbidden", "❌ Недостаточно прав для этого действия."),
        ("flood control", "❌ Слишком много запросов, попробуйте чуть позже."),
        ("too many requests", "❌ Слишком много запросов, попробуйте чуть позже."),
        ("peer_id_invalid", "❌ Не удалось найти получателя."),
    ]
    for needle, text in mapping:
        if needle in raw:
            return text
    return "❌ Не удалось выполнить действие. Попробуйте ещё раз чуть позже."

def display_name(username, first_name, last_name):
    name = " ".join(p for p in (first_name, last_name) if p)
    if not name:
        name = username or "пользователь"
    return name

def user_link(user_id, name, tag=True):
    if tag:
        return f'<a href="tg://user?id={user_id}">{html.escape(name)}</a>'
    return f'<b>{html.escape(name)}</b>'

def tg_user_link(user, tag=True):
    name = display_name(user.username, user.first_name, user.last_name)
    return user_link(user.id, name, tag=tag)

def parse_duration(token):
    m = re.match(r"^(\d+)([hdmy])$", token, re.IGNORECASE)
    if not m:
        return None
    amount, unit = int(m.group(1)), m.group(2).lower()
    units = {"h": 3600, "d": 86400, "m": 60, "y": 365 * 86400}
    return timedelta(seconds=amount * units[unit])

def format_duration(td):
    total = int(td.total_seconds())
    units = {"y": 365 * 86400, "d": 86400, "h": 3600, "m": 60}
    names = {"y": "г", "d": "д", "h": "ч", "m": "мин"}
    for unit, sec in units.items():
        if total % sec == 0 and total // sec > 0:
            return f"{total // sec}{names[unit]}"
    return f"{total}с"

def get_mute_duration(level):
    if level <= 0 or level > len(MUTE_LEVELS):
        return 60
    return MUTE_LEVELS[level - 1]

_PROFANITY_ROOTS = [r"[хx][уy][ий]", r"п[иеё]зд", r"ебл", r"[её]б[аоыи]", r"бля[дт]", r"мудак", r"сука", r"пидор", r"гандон", r"мраз", r"тварь", r"шлюх", r"нах[уy][ий]"]
_PROFANITY_RE = re.compile("|".join(_PROFANITY_ROOTS), re.IGNORECASE)
_LEET_MAP = {"0": "о", "a": "а", "@": "а", "b": "б", "e": "е", "3": "з", "y": "у", "u": "у", "i": "и", "1": "и", "!": "и", "o": "о", "p": "р", "x": "х", "h": "х", "c": "с", "k": "к", "m": "м", "t": "т"}

def _normalize_for_profanity(text: str) -> str:
    if not text:
        return ""
    t = text.lower()
    t = re.sub(r"[\s\.\-_*\u200b]+", "", t)
    t = "".join(_LEET_MAP.get(ch, ch) for ch in t)
    t = re.sub(r"(.)\1{1,}", r"\1", t)
    return t

def is_profane(text: str, extra_words: Optional[List[str]] = None) -> bool:
    if not text:
        return False
    normalized = _normalize_for_profanity(text)
    if _PROFANITY_RE.search(normalized) or _PROFANITY_RE.search(text.lower()):
        return True
    if extra_words:
        return contains_banned_words(text, extra_words)
    return False

def contains_banned_words(text: str, words: Optional[List[str]]) -> bool:
    if not text or not words:
        return False
    normalized = _normalize_for_profanity(text)
    lower = text.lower()
    for w in words:
        w = w.lower().strip()
        if not w:
            continue
        w_norm = _normalize_for_profanity(w)
        if w_norm and w_norm in normalized:
            return True
        if w in lower:
            return True
    return False

