    async def _cb_report_action(self, update, context, report_id, action):
        query = update.callback_query
        report = self.db.get_report(report_id)
        if not report:
            await query.answer("Репорт не найден.", show_alert=True)
            return
        _, chat_id, reporter_id, target_id, target_name, reason, message_id, status = report
        admin = query.from_user
        if not await self._can_moderate(chat_id, admin.id):
            await query.answer("Только для модераторов.", show_alert=True)
            return
        if status != "pending":
            await query.answer("Репорт уже обработан.", show_alert=True)
            return
        protect_error = await self._target_is_protected(chat_id, admin.id, target_id)
        if protect_error:
            await query.answer(protect_error, show_alert=True)
            return

        complaint_reason = "Жалоба от пользователя" + (f": {reason}" if reason else "")
        result_label = {"mute": "🔇 Мут", "ban": "🔨 Бан", "warn": "⚠️ Варн"}[action]

        try:
            if action == "ban":
                await context.bot.ban_chat_member(chat_id, target_id)
                self.db.log_action(chat_id, target_id, "ban", admin.id, complaint_reason)
                self.db.add_restriction(chat_id, target_id, "ban", target_name, complaint_reason)
                public_text = build_action_text("🔨", "забанен(а)", user_link(target_id, target_name), complaint_reason, admin_html=tg_user_link(admin))
                pub_kb = InlineKeyboardMarkup([[InlineKeyboardButton("🔓 Разбанить", callback_data=f"unban_{chat_id}_{target_id}")]])
            elif action == "mute":
                count = self.db.increment_report_punish_count(chat_id, target_id)
                durations = {1: 3600, 2: 10800, 3: 43200}
                duration_sec = durations.get(count, 86400)
                until = datetime.now(timezone.utc) + timedelta(seconds=duration_sec)
                await context.bot.restrict_chat_member(chat_id, target_id, permissions=no_permissions(), until_date=until)
                self.db.log_action(chat_id, target_id, "mute", admin.id, complaint_reason, duration_sec)
                self.db.add_restriction(chat_id, target_id, "mute", target_name, complaint_reason, int(until.timestamp()))
                public_text = build_action_text("🔇", "замучен(а)", user_link(target_id, target_name), complaint_reason, duration_text=format_duration(timedelta(seconds=duration_sec)), admin_html=tg_user_link(admin))
                pub_kb = InlineKeyboardMarkup([[InlineKeyboardButton("🔊 Снять мут", callback_data=f"unmute_{chat_id}_{target_id}")]])
            else:
                count = self.db.add_warn(chat_id, target_id, complaint_reason)
                self.db.log_action(chat_id, target_id, "warn", admin.id, complaint_reason)
                public_text = f"⚠️ {user_link(target_id, target_name)} получил(а) предупреждение ({count}/3).\n📃Причина: {html.escape(complaint_reason)}\n🛡️Администратор: {tg_user_link(admin)}"
                pub_kb = InlineKeyboardMarkup([[InlineKeyboardButton("♻️ Снять предупреждение", callback_data=f"unwarn_{chat_id}_{target_id}")]])
        except TelegramError as e:
            await query.answer(friendly_tg_error(e), show_alert=True)
            return

        self.db.set_report_status(report_id, f"punished:{action}")
        try:
            await context.bot.send_message(chat_id, public_text, parse_mode=ParseMode.HTML, reply_markup=pub_kb)
        except TelegramError:
            pass
        await query.answer("Наказание применено.")
        try:
            base = query.message.text_html or query.message.text or ""
            await query.message.edit_text(base + f"\n\n{result_label} применено {tg_user_link(admin)}.", parse_mode=ParseMode.HTML)
        except TelegramError:
            pass

    async def cmd_clear(self, update, context):
        if not await self._guard_group_allowed(update, context):
            return
        if not await self._require_group_and_perm(update, context):
            return
        message = update.effective_message
        chat_id = update.effective_chat.id
        args = context.args or []
        if not args or not args[0].isdigit():
            return
        target = int(args[0])
        if target <= 0:
            return

        protected = self.db.get_protected_messages(chat_id)
        try:
            await message.delete()
        except TelegramError:
            pass

        deleted = 0
        msg_id = message.message_id - 1
        max_attempts = target * 10 + 200
        attempts = 0
        while deleted < target and msg_id > 0 and attempts < max_attempts:
            attempts += 1
            if msg_id in protected:
                msg_id -= 1
                continue
            try:
                await context.bot.delete_message(chat_id, msg_id)
                deleted += 1
            except TelegramError:
                pass
            msg_id -= 1
            if deleted and deleted % 100 == 0:
                await asyncio.sleep(3)

    def _msg_link(self, chat, message_id):
        if getattr(chat, "username", None):
            return f"https://t.me/{chat.username}/{message_id}"
        cid = str(chat.id)
        if cid.startswith("-100"):
            cid = cid[4:]
        else:
            cid = cid.lstrip("-")
        return f"https://t.me/c/{cid}/{message_id}"

    async def cmd_date(self, update, context):
        message = update.effective_message
        chat = update.effective_chat
        try:
            if chat.type == ChatType.PRIVATE:
                return
            uid = update.effective_user.id
            has_access = uid in ADMIN_ID or self.is_panel_admin(uid)
            if not has_access:
                return
            replied = message.reply_to_message
            if not replied or not replied.from_user:
                return
            args = context.args or []
            if len(args) < 2:
                return
            date_str = f"{args[0]} {args[1]}"
            try:
                dt = datetime.strptime(date_str, "%d.%m.%Y %H:%M")
            except ValueError:
                return
            ts = int(dt.timestamp())
            self.db.set_joined_at(chat.id, replied.from_user.id, ts)
        except Exception:
            logger.exception("Ошибка в /date")
        finally:
            try:
                await message.delete()
            except TelegramError:
                pass

    async def cmd_info(self, update, context):
        if not await self._guard_group_allowed(update, context):
            return
        chat = update.effective_chat
        if chat.type == ChatType.PRIVATE:
            await update.message.reply_text("Эта команда работает только в группах.")
            return
        if not await self._can_moderate(chat.id, update.effective_user.id):
            return
        try:
            target_id, name, _, error = await self._resolve_target(update, context)
            target_user = None
            searched_username = None
            args = context.args
            if args and args[0].startswith("@"):
                searched_username = args[0][1:]
            if not target_id:
                if error:
                    await update.message.reply_text(error)
                    return
                u = update.effective_user
                target_id, name = u.id, display_name(u.username, u.first_name, u.last_name)
                target_user = u
            elif update.effective_message.reply_to_message:
                target_user = update.effective_message.reply_to_message.from_user

            member = None
            try:
                member = await context.bot.get_chat_member(chat.id, target_id)
                if target_user is None and member.user:
                    target_user = member.user
            except TelegramError:
                member = None

            meta = self.db.get_user_meta(chat.id, target_id)
            username = (target_user.username if target_user else None) or (meta[0] if meta else None) or searched_username
            first_name = (target_user.first_name if target_user else None) or (meta[1] if meta else None) or name
            last_name = (target_user.last_name if target_user else None) or (meta[2] if meta else None)
            joined_at = meta[3] if meta else None
            lang_code = (target_user.language_code if target_user else None) or (meta[4] if meta else None)

            warns, _ = self.db.get_warns(chat.id, target_id)
            is_staff = self.db.is_staff(chat.id, target_id)
            owner_id, _, _ = self.db.get_owner(chat.id)

            restriction = self.db.get_restriction(chat.id, target_id)
            has_restriction = restriction is not None

            state = "👀 Участник"
            kb_rows = []
            if member:
                if member.status == ChatMemberStatus.BANNED:
                    state = "🔨 Забанен(а)"
                elif member.status == ChatMemberStatus.RESTRICTED and not member.can_send_messages:
                    state = "🔇 В муте"
                elif member.status == ChatMemberStatus.LEFT:
                    state = "🚪 Покинул(а) чат"
                elif member.status in (ChatMemberStatus.OWNER, ChatMemberStatus.ADMINISTRATOR):
                    state = "🛡 Администратор" if member.status == ChatMemberStatus.ADMINISTRATOR else "👑 Владелец"
            else:
                state = "🚪 Не найден(а) в чате"

            lang_names = {"ru": "Russian", "en": "English", "uk": "Ukrainian", "kk": "Kazakh", "be": "Belarusian"}
            lang_display = lang_names.get(lang_code, lang_code.capitalize()) if lang_code else "—"
            joined_display = datetime.fromtimestamp(joined_at).strftime("%d.%m.%y в %H:%M") if joined_at else "неизвестно"

            lines = [
                f"<b>wT2x2 Moderator</b>",
                f"🆔 <b>ID</b>: <code>{target_id}</code> #id{target_id}",
                f"👤 <b>Имя</b>: {html.escape(first_name or '—')}",
            ]
            if last_name:
                lines.append(f"👥 <b>Фамилия</b>: \"{html.escape(last_name)}\"")
            lines.append(f"🌐 <b>Имя пользователя</b>: {('@' + username) if username else '—'}")
            lines.append(f"👀 <b>Состояние</b>: {state}")
            lines.append(f"❗ <b>Предупреждения</b>: {warns}/3")
            lines.append(f"↳ <b>Вступил(а)</b>: {joined_display}")
            lines.append(f"🇷🇺 <b>Язык</b>: {lang_display}")
            text = "\n".join(lines)

            if has_restriction:
                rtype = restriction[0]
                if rtype == "ban":
                    kb_rows.append([InlineKeyboardButton("🔓 Разблокировать", callback_data=f"unban_{chat.id}_{target_id}")])
                elif rtype == "mute":
                    kb_rows.append([InlineKeyboardButton("🔊 Снять ограничение", callback_data=f"unmute_{chat.id}_{target_id}")])
            else:
                kb_rows.append([InlineKeyboardButton("❗ Предупреждения", callback_data=f"infowarns_{chat.id}_{target_id}")])
                kb_rows.append([
                    InlineKeyboardButton("🔪 Ограничить", callback_data=f"inforestrict_{chat.id}_{target_id}"),
                    InlineKeyboardButton("🚫 Заблокировать", callback_data=f"infoban_{chat.id}_{target_id}"),
                ])
                kb_rows.append([InlineKeyboardButton("🕹 Разрешения", callback_data=f"inforights_{chat.id}_{target_id}")])

            kb = InlineKeyboardMarkup(kb_rows)
            await update.message.reply_text(text, parse_mode=ParseMode.HTML, reply_markup=kb)
        except Exception:
            logger.exception("Ошибка в /info")
            await update.message.reply_text("⚠️ Не удалось получить информацию.")

    async def _fetch_tag(self, context, chat_id, user_id):
        """Достаём текущий @username участника через Telegram API (getChatMember)."""
        try:
            member = await context.bot.get_chat_member(chat_id, user_id)
            u = member.user
            return f"@{u.username}" if u.username else None
        except TelegramError:
            return None

    async def _smart_link(self, context, chat_id, user_id, display_name):
        """Ссылка на t.me/username если юз есть, иначе tg://user?id= по ID."""
        username = None
        try:
            member = await context.bot.get_chat_member(chat_id, user_id)
            username = member.user.username
        except TelegramError:
            pass
        name = html.escape(display_name or str(user_id))
        if username:
            return f'<a href="https://t.me/{username}">{name}</a>'
        return user_link(user_id, display_name or str(user_id), tag=False)

    async def cmd_staff(self, update, context):
        if not await self._guard_group_allowed(update, context):
            return
        chat = update.effective_chat
        if chat.type == ChatType.PRIVATE:
            await update.message.reply_text("Эта команда работает только в группах.")
            return
        staff = self.db.list_staff(chat.id)
        owner_id, owner_username, _ = self.db.get_owner(chat.id)
        lines = ["🛡 Список Админов\n"]
        if owner_id:
            link = await self._smart_link(context, chat.id, owner_id, owner_username)
            lines.append(f"👑 {link} — владелец")
        if staff:
            for uid, name in staff:
                link = await self._smart_link(context, chat.id, uid, name)
                lines.append(f"🛡 {link} — Админ")
        else:
            lines.append("Админы пока не назначены.")
        await update.message.reply_text("\n".join(lines), parse_mode=ParseMode.HTML, disable_web_page_preview=True)

