def reset_all_limits():
    conn = get_emir_conn()
    c = conn.cursor()
    c.execute('DELETE FROM game_limits')
    conn.commit()
    conn.close()

def can_play(user_id):
    max_plays = get_max_attempts()
    conn = get_emir_conn()
    c = conn.cursor()
    c.execute('SELECT plays, reset_time FROM game_limits WHERE user_id = ?', (user_id,))
    row = c.fetchone()
    conn.close()
    now = time.time()
    if row:
        plays, reset_time = row
        if now > reset_time:
            return True, reset_time, max_plays
        elif plays < max_plays:
            return True, reset_time, max_plays - plays
        else:
            return False, reset_time, 0
    return True, 0, max_plays

def record_play(user_id):
    conn = get_emir_conn()
    c = conn.cursor()
    c.execute('SELECT plays, reset_time FROM game_limits WHERE user_id = ?', (user_id,))
    row = c.fetchone()
    now = time.time()
    is_first_play = False
    reset_time = now + 86400
    if row:
        plays, old_reset_time = row
        if now > old_reset_time:
            c.execute('UPDATE game_limits SET plays = 1, reset_time = ? WHERE user_id = ?', (reset_time, user_id))
            is_first_play = True
        else:
            c.execute('UPDATE game_limits SET plays = plays + 1 WHERE user_id = ?', (user_id,))
            reset_time = old_reset_time
    else:
        c.execute('INSERT INTO game_limits (user_id, plays, reset_time) VALUES (?, 1, ?)', (user_id, reset_time))
        is_first_play = True
    conn.commit()
    conn.close()
    return is_first_play, reset_time

def add_user(user_id):
    conn = get_emir_conn()
    c = conn.cursor()
    c.execute('INSERT OR IGNORE INTO users (user_id, joined_at) VALUES (?, ?)', (user_id, int(time.time())))
    conn.commit()
    conn.close()

def get_users_this_month():
    conn = get_emir_conn()
    c = conn.cursor()
    now = datetime.now()
    month_start = int(datetime(now.year, now.month, 1).timestamp())
    c.execute('SELECT COUNT(*) FROM users WHERE joined_at IS NOT NULL AND joined_at >= ?', (month_start,))
    count = c.fetchone()[0]
    conn.close()
    return count

def log_stat(action):
    conn = get_emir_conn()
    c = conn.cursor()
    c.execute('INSERT INTO stats (action, count) VALUES (?, 1) ON CONFLICT(action) DO UPDATE SET count = count + 1', (action,))
    conn.commit()
    conn.close()

def add_stars_earned(amount):
    conn = get_emir_conn()
    c = conn.cursor()
    c.execute('INSERT INTO stats (action, count) VALUES (?, ?) ON CONFLICT(action) DO UPDATE SET count = count + ?', ("stars_earned", amount, amount))
    conn.commit()
    conn.close()

