async def chat_auto_reply(update: Update, context: ContextTypes.DEFAULT_TYPE):
    logger.info(f"chat_auto_reply: получено сообщение {update.message.message_id} в чате {update.effective_chat.id}, is_automatic_forward={getattr(update.message, 'is_automatic_forward', None)}, sender_chat={getattr(update.message, 'sender_chat', None)}")
    if getattr(update.message, 'is_automatic_forward', False):
        chat_id = update.effective_chat.id
        moderator.db.add_protected_message(chat_id, update.message.message_id)
        auto_chat_id, auto_msg_id = get_auto_reply()
        try:
            if auto_chat_id and auto_msg_id:
                sent = await context.bot.copy_message(
                    chat_id=update.effective_chat.id,
                    from_chat_id=auto_chat_id,
                    message_id=auto_msg_id,
                    reply_to_message_id=update.message.message_id
                )
            else:
                quoted_text = f"<blockquote expandable>{html.escape(DEFAULT_AUTOREPLY_TEXT)}</blockquote>"
                sent = await update.message.reply_text(quoted_text, reply_to_message_id=update.message.message_id, parse_mode=ParseMode.HTML)
            moderator.db.add_protected_message(chat_id, sent.message_id)
            if get_auto_donate_enabled():
                try:
                    donate_sent = await context.bot.send_message(
                        chat_id=update.effective_chat.id,
                        text=DONATE_AUTOREPLY_TEXT,
                        reply_to_message_id=update.message.message_id,
                        reply_markup=donate_autoreply_kb(),
                        parse_mode=ParseMode.HTML,
                    )
                    moderator.db.add_protected_message(chat_id, donate_sent.message_id)
                except Exception as e:
                    logger.error(f"chat_auto_reply: ошибка отправки авто-доната: {e}")
        except Exception as e:
            logger.error(f"chat_auto_reply: ошибка отправки автоответа: {e}")
        try:
            result = await context.bot.unpin_chat_message(chat_id=update.effective_chat.id, message_id=update.message.message_id)
            logger.info(f"chat_auto_reply: открепление поста {update.message.message_id} в чате {update.effective_chat.id} -> {result}")
        except TelegramError as e:
            logger.error(f"chat_auto_reply: не удалось открепить пост {update.message.message_id} в чате {update.effective_chat.id}: {e}")

async def handle_pinned_service_message(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    Подстраховка: если Telegram всё же присылает служебное сообщение о закрепе
    (например, для будущих версий API или иных сценариев), открепляем только
    закрепы автопостов без реального инициатора-человека. Для стандартного
    молчаливого автозакрепа поста из привязанного канала это событие обычно
    НЕ приходит боту вообще — основную работу делает unpin в chat_auto_reply выше.
    """
    msg = update.message
    pinned = getattr(msg, 'pinned_message', None)
    if not pinned:
        return
    is_auto_post = getattr(pinned, 'is_automatic_forward', False)
    pinner = msg.from_user
    pinned_by_human = bool(pinner) and not pinner.is_bot
    logger.info(f"handle_pinned_service_message: pinned_id={pinned.message_id} is_auto_post={is_auto_post} pinner={pinner.id if pinner else None} pinned_by_human={pinned_by_human}")
    if is_auto_post and not pinned_by_human:
        try:
            await context.bot.unpin_chat_message(chat_id=msg.chat_id, message_id=pinned.message_id)
        except TelegramError as e:
            logger.error(f"handle_pinned_service_message: ошибка открепления {pinned.message_id}: {e}")

async def start(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if update.effective_chat.type != "private":
        return
    add_user(update.effective_user.id)
    log_stat("cmd_start")
    args = context.args
    if args and args[0].startswith("appeal_"):
        await moderator.handle_appeal_deeplink(update, context, args[0])
        return
    if args and args[0].startswith("rules_"):
        await moderator.handle_rules_deeplink(update, context, args[0])
        return
    if args and args[0] == "cryptopay":
        await update.message.reply_text(
            "Нравятся нарезки? Ты можешь скинуть мне денек на еду в подвал😋",
            reply_markup=donatee(),
            parse_mode="HTML",
        )
        return
    if args and args[0] == "donate_stars":
        await update.message.reply_text(
            "Нравятся нарезки? Ты можешь скинуть мне денек на еду в подвал😋",
            reply_markup=donatee(),
            parse_mode="HTML",
        )
        return
    if args and args[0] == "donate":
        await update.message.reply_text(
            "Нравятся нарезки? Ты можешь скинуть мне денек на еду в подвал😋",
            reply_markup=donatee(),
            parse_mode="HTML",
        )
        return
    await show_main_menu(update, context, is_callback=False)

