async def _finalize_full_media(context: ContextTypes.DEFAULT_TYPE):
    job_data = context.job.data
    code = job_data['code']
    chat_id = job_data['chat_id']
    message_ids = job_data['message_ids']
    conn = get_emir_conn()
    c = conn.cursor()
    c.execute(
        'INSERT OR REPLACE INTO fulls (code, from_chat_id, message_id, message_ids) VALUES (?, ?, ?, ?)',
        (code, chat_id, message_ids[0], ",".join(str(i) for i in message_ids))
    )
    conn.commit()
    conn.close()
    await context.bot.send_message(chat_id=chat_id, text=f"✅ Фулл по коду <b>{code}</b> сохранен! ({len(message_ids)} медиа)", parse_mode="HTML")

async def add_full_media(update: Update, context: ContextTypes.DEFAULT_TYPE):
    code = context.user_data['full_code']
    chat_id = update.effective_chat.id
    media_group_id = update.message.media_group_id

    if media_group_id:
        buf = context.user_data.setdefault('full_media_groups', {})
        group = buf.setdefault(media_group_id, [])
        group.append(update.message.message_id)

        old_job = context.user_data.get('full_media_job')
        if old_job:
            old_job.schedule_removal()

        job = context.job_queue.run_once(
            _finalize_full_media,
            1.5,
            data={'code': code, 'chat_id': chat_id, 'message_ids': list(group)},
        )
        context.user_data['full_media_job'] = job
        return FULL_MEDIA_ADD

    conn = get_emir_conn()
    c = conn.cursor()
    c.execute(
        'INSERT OR REPLACE INTO fulls (code, from_chat_id, message_id, message_ids) VALUES (?, ?, ?, ?)',
        (code, chat_id, update.message.message_id, str(update.message.message_id))
    )
    conn.commit()
    conn.close()
    await update.message.reply_text(f"✅ Фулл по коду <b>{code}</b> сохранен!", parse_mode="HTML")
    return ConversationHandler.END

