async def get_full_send(update: Update, context: ContextTypes.DEFAULT_TYPE):
    code = update.message.text.strip()
    user_id = update.effective_user.id if update.effective_user else None
    logger.info(f"get_full_send: получен код '{code}' от пользователя {user_id}")
    try:
        conn = get_emir_conn()
        c = conn.cursor()
        c.execute('SELECT from_chat_id, message_id, message_ids FROM fulls WHERE code = ?', (code,))
        res = c.fetchone()
        conn.close()
        if res:
            from_chat_id, message_id, message_ids = res
            ids = [int(i) for i in message_ids.split(",")] if message_ids else [message_id]
            if len(ids) > 1:
                try:
                    await context.bot.copy_messages(chat_id=update.effective_chat.id, from_chat_id=from_chat_id, message_ids=ids)
                except (TelegramError, AttributeError) as e:
                    logger.warning(f"get_full_send: copy_messages не сработал ({e}), отправляю по одному")
                    for mid in ids:
                        await context.bot.copy_message(chat_id=update.effective_chat.id, from_chat_id=from_chat_id, message_id=mid)
            else:
                await context.bot.copy_message(chat_id=update.effective_chat.id, from_chat_id=from_chat_id, message_id=ids[0])
            logger.info(f"get_full_send: фулл по коду '{code}' отправлен пользователю {user_id}")
        else:
            logger.info(f"get_full_send: код '{code}' не найден в базе")
            await update.message.reply_text("❌ Код не найден.")
    except Exception as e:
        logger.error(f"get_full_send: ошибка при обработке кода '{code}' от {user_id}: {e}")
        try:
            await update.message.reply_text("⚠️ Произошла ошибка, попробуй ещё раз.")
        except TelegramError:
            pass
    return ConversationHandler.END

