CRYPTO_MIN_AMOUNT = 0.5

async def donate_crypto_process(update: Update, context: ContextTypes.DEFAULT_TYPE):
    text = update.message.text.strip().replace(',', '.')
    try:
        amount = float(text)
        if amount <= 0: raise ValueError
    except ValueError:
        await update.message.reply_text("❌ Введите корректное число.")
        return DONATE_AMOUNT_WAIT
    if amount < CRYPTO_MIN_AMOUNT:
        await update.message.reply_text(f"❌ Минимальная сумма доната — {CRYPTO_MIN_AMOUNT}$. Введите число не меньше {CRYPTO_MIN_AMOUNT}.")
        return DONATE_AMOUNT_WAIT
    await update.message.reply_text("⏳ Генерирую счет...")
    url = "https://pay.crypt.bot/api/createInvoice"
    headers = {"Crypto-Pay-API-Token": CRYPTO_TOKEN}
    payload = {"currency_type": "fiat", "fiat": "USD", "amount": str(amount), "description": "Донат на развитие"}
    async with httpx.AsyncClient() as client:
        try:
            response = await client.post(url, headers=headers, json=payload, timeout=10.0)
            data = response.json()
            if data.get("ok"):
                invoice_id = data["result"]["invoice_id"]
                kb = InlineKeyboardMarkup([
                    [InlineKeyboardButton("💸 Оплатить", url=data["result"]["pay_url"])],
                    [InlineKeyboardButton("✅ Я оплатил", callback_data=f"cryptocheck_{invoice_id}")],
                    [InlineKeyboardButton("« В меню", callback_data="startt")]
                ])
                await update.message.reply_text(f"✅ <b>Счет на {amount}$ создан!</b>\n\nПосле оплаты нажми «Я оплатил».", reply_markup=kb, parse_mode="HTML")
            else:
                error_msg = data.get("error", {}).get("name", "Неизвестная ошибка")
                await update.message.reply_text(f"❌ Ошибка: {error_msg}", parse_mode="HTML")
        except Exception as e:
            await update.message.reply_text(f"❌ Ошибка соединения: {e}")
    return ConversationHandler.END

async def cryptocheck_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    invoice_id = query.data.split("_", 1)[1]
    user = query.from_user
    headers = {"Crypto-Pay-API-Token": CRYPTO_TOKEN}
    try:
        async with httpx.AsyncClient() as client:
            response = await client.get("https://pay.crypt.bot/api/getInvoices", headers=headers, params={"invoice_ids": invoice_id}, timeout=10.0)
            data = response.json()
        items = data.get("result", {}).get("items", []) if data.get("ok") else []
        invoice = items[0] if items else None
        if not invoice:
            await query.answer("Счёт не найден.", show_alert=True)
            return
        if invoice.get("status") == "paid":
            await query.answer("✅ Оплата подтверждена, спасибо!", show_alert=True)
            amount = invoice.get("amount")
            fiat = invoice.get("fiat", "")
            username = f"@{user.username}" if user.username else f"ID {user.id}"
            try:
                await query.edit_message_reply_markup(reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("« В меню", callback_data="startt")]]))
            except Exception:
                pass
            for admin_id in ADMIN_ID:
                try:
                    await context.bot.send_message(
                        chat_id=admin_id,
                        text=f"💎 <b>Новый донат через Crypto Bot!</b>\nОт: {username}\nСумма: {amount} {fiat}",
                        parse_mode="HTML",
                        reply_markup=donor_admin_reply_kb(user.id),
                    )
                except Exception:
                    pass
        else:
            await query.answer("❌ Оплата пока не найдена. Подожди немного и попробуй снова.", show_alert=True)
    except Exception:
        await query.answer("❌ Не удалось проверить оплату. Попробуй ещё раз.", show_alert=True)

