import hmac as _wt_hmac
import secrets as _wt_secrets
import hashlib as _wt_hashlib
import zlib as _wt_zlib
import threading as _wt_threading
import urllib.request as _wt_urlreq
import urllib.parse as _wt_urlparse
import html as _wt_html
from contextlib import contextmanager as _wt_contextmanager
from http.server import ThreadingHTTPServer as _WtServer, BaseHTTPRequestHandler as _WtBaseHandler

WEBAPP_DOMAIN = str(_cfg.get("webapp_domain") or "rendastars.website").strip().lower()
WEBAPP_URL = f"https://{WEBAPP_DOMAIN}"
WEB_HOST = "127.0.0.1"
WEB_PORT = int(_cfg.get("web_port") or 8080)
WEBAPP_OVERRIDE = os.path.join(BASE_DIR, "webapp.html")
WT_START_BALANCE = 500
WT_BONUS_AMOUNT = 500
WT_BONUS_COOLDOWN = 20 * 3600
WT_MAX_BALANCE = 10 ** 9
WT_ORDER_COOLDOWN = 7 * 24 * 3600
WT_MSK = timezone(timedelta(hours=3))
WT_MAX_BODY = 8 * 1024 * 1024
WT_ACCEPT_LOCAL_CLAIM = False

class WtError(Exception):
    def __init__(self, code, msg):
        super().__init__(msg)
        self.code = code
        self.msg = msg

def _wt_int(v, lo, hi, default=0):
    try:
        n = int(v)
    except (TypeError, ValueError):
        return default
    return max(lo, min(hi, n))

def wt_today():
    return datetime.now(WT_MSK).strftime("%Y-%m-%d")

def wt_fmt_ts(ts):
    return datetime.fromtimestamp(int(ts), WT_MSK).strftime("%d.%m %H:%M МСК")

def _wt_conn():
    conn = sqlite3.connect(EMIR_DB_PATH, timeout=15, isolation_level=None)
    conn.row_factory = sqlite3.Row
    conn.execute("PRAGMA busy_timeout=15000")
    return conn

@_wt_contextmanager
def wt_tx():
    conn = _wt_conn()
    try:
        conn.execute("BEGIN IMMEDIATE")
        yield conn
        conn.execute("COMMIT")
    except BaseException:
        try:
            conn.execute("ROLLBACK")
        except Exception:
            pass
        raise
    finally:
        conn.close()

def wt_init_db():
    """Только CREATE TABLE IF NOT EXISTS — существующие данные никогда не удаляются."""
    conn = _wt_conn()
    conn.execute("""CREATE TABLE IF NOT EXISTS wt_users (
        user_id INTEGER PRIMARY KEY, first_name TEXT DEFAULT '', last_name TEXT DEFAULT '', username TEXT DEFAULT '',
        balance INTEGER NOT NULL DEFAULT 500, won INTEGER NOT NULL DEFAULT 0, lost INTEGER NOT NULL DEFAULT 0,
        day_date TEXT DEFAULT '', day_amount INTEGER NOT NULL DEFAULT 0, day_game TEXT DEFAULT '',
        created_at INTEGER, last_seen INTEGER)""")
    conn.execute("""CREATE TABLE IF NOT EXISTS wt_products (
        id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, descr TEXT DEFAULT '', price INTEGER NOT NULL,
        stock INTEGER NOT NULL DEFAULT 0, image TEXT DEFAULT '', anim TEXT DEFAULT '',
        is_prize INTEGER NOT NULL DEFAULT 0, active INTEGER NOT NULL DEFAULT 1, created_at INTEGER)""")
    conn.execute("""CREATE TABLE IF NOT EXISTS wt_orders (
        id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, product_id INTEGER, title TEXT, price INTEGER,
        comment TEXT DEFAULT '', status TEXT NOT NULL DEFAULT 'new', msgs TEXT DEFAULT '[]',
        created_at INTEGER, closed_at INTEGER, closed_by INTEGER)""")
    conn.execute("CREATE INDEX IF NOT EXISTS wt_orders_user ON wt_orders (user_id, created_at)")
    try:
        conn.execute("ALTER TABLE wt_products ADD COLUMN limit_days INTEGER")
    except sqlite3.OperationalError:
        pass
    conn.execute("CREATE INDEX IF NOT EXISTS wt_orders_user_prod ON wt_orders (user_id, product_id, created_at)")
    for col in ("bonus_at", "bonus_notified"):
        try:
            conn.execute(f"ALTER TABLE wt_users ADD COLUMN {col} INTEGER NOT NULL DEFAULT 0")
        except sqlite3.OperationalError:
            pass
    conn.execute("CREATE TABLE IF NOT EXISTS wt_settings (key TEXT PRIMARY KEY, value TEXT NOT NULL DEFAULT '')")
    conn.execute("""CREATE TABLE IF NOT EXISTS wt_tasks (
        id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, reward INTEGER NOT NULL, link TEXT NOT NULL,
        chat TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1, created_at INTEGER)""")
    conn.execute("""CREATE TABLE IF NOT EXISTS wt_task_done (
        user_id INTEGER NOT NULL, task_id INTEGER NOT NULL, reward INTEGER NOT NULL DEFAULT 0, created_at INTEGER,
        PRIMARY KEY (user_id, task_id))""")
    conn.execute("CREATE TABLE IF NOT EXISTS wt_bonuses (id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, reward INTEGER NOT NULL, active INTEGER NOT NULL DEFAULT 1, created_at INTEGER)")
    conn.execute("CREATE TABLE IF NOT EXISTS wt_bonus_done (user_id INTEGER NOT NULL, bonus_id INTEGER NOT NULL, reward INTEGER NOT NULL DEFAULT 0, created_at INTEGER, PRIMARY KEY (user_id, bonus_id))")
    conn.execute("CREATE TABLE IF NOT EXISTS wt_terms (user_id INTEGER PRIMARY KEY, accepted_at INTEGER)")
    for col, ddl in (("sync_dev", "TEXT NOT NULL DEFAULT ''"), ("sync_seq", "INTEGER NOT NULL DEFAULT -1"), ("sync_bal", "INTEGER NOT NULL DEFAULT 0")):
        try:
            conn.execute(f"ALTER TABLE wt_users ADD COLUMN {col} {ddl}")
        except sqlite3.OperationalError:
            pass
    conn.execute("CREATE TABLE IF NOT EXISTS wt_crash_rounds (id INTEGER PRIMARY KEY, start_at INTEGER NOT NULL, crash_at INTEGER NOT NULL, point REAL NOT NULL)")
    conn.execute("""CREATE TABLE IF NOT EXISTS wt_bets (
        id INTEGER PRIMARY KEY AUTOINCREMENT, game TEXT NOT NULL, round_id INTEGER NOT NULL, user_id INTEGER NOT NULL,
        amount INTEGER NOT NULL, choice TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'open',
        payout INTEGER NOT NULL DEFAULT 0, mult REAL NOT NULL DEFAULT 0, result TEXT NOT NULL DEFAULT '', created_at INTEGER)""")
    conn.execute("CREATE UNIQUE INDEX IF NOT EXISTS wt_bets_uniq ON wt_bets (game, round_id, user_id)")
    conn.execute("CREATE INDEX IF NOT EXISTS wt_bets_open ON wt_bets (status, game, round_id)")
    if not wt_get_setting(conn, "games_secret", ""):
        wt_set_setting(conn, "games_secret", _wt_secrets.token_hex(32))
    conn.execute("UPDATE wt_products SET limit_days=? WHERE limit_days IS NULL", (wt_limit_days(conn),))
    conn.close()

def wt_parse_init_data(init_data):
    """Проверка подписи Telegram WebApp initData (HMAC-SHA256 по токену бота) -> словарь пользователя."""
    if not init_data:
        raise WtError(401, "Откройте Mini App через Telegram")
    try:
        pairs = dict(_wt_urlparse.parse_qsl(init_data, keep_blank_values=True, strict_parsing=True))
    except ValueError:
        raise WtError(401, "Некорректные данные Telegram")
    received = pairs.pop("hash", None)
    if not received:
        raise WtError(401, "Нет подписи Telegram")
    check = "\n".join(f"{k}={v}" for k, v in sorted(pairs.items()))
    secret = _wt_hmac.new(b"WebAppData", TOKEN.encode(), _wt_hashlib.sha256).digest()
    expected = _wt_hmac.new(secret, check.encode(), _wt_hashlib.sha256).hexdigest()
    if not _wt_hmac.compare_digest(expected, received):
        raise WtError(401, "Неверная подпись Telegram")
    if time.time() - _wt_int(pairs.get("auth_date"), 0, 10 ** 12, 0) > 3 * 86400:
        raise WtError(401, "Сессия устарела — откройте Mini App заново")
    try:
        user = json.loads(pairs.get("user") or "{}")
    except ValueError:
        user = {}
    if not isinstance(user, dict) or not user.get("id"):
        raise WtError(401, "Не удалось определить пользователя")
    user["id"] = int(user["id"])
    return user

def wt_name(row):
    full = " ".join(x for x in [(row["first_name"] or "").strip(), (row["last_name"] or "").strip()] if x)
    if full:
        return full
    if row["username"]:
        return "@" + row["username"]
    return "Игрок"

def _wt_ensure_user(conn, tg, claim=None):
    row = conn.execute("SELECT * FROM wt_users WHERE user_id=?", (tg["id"],)).fetchone()
    now = int(time.time())
    first = str(tg.get("first_name") or "")[:64]
    last = str(tg.get("last_name") or "")[:64]
    uname = str(tg.get("username") or "")[:64]
    if row is None:
        bal, won, lost, dd, da, dg = WT_START_BALANCE, 0, 0, "", 0, ""
        if WT_ACCEPT_LOCAL_CLAIM and isinstance(claim, dict):
            bal = _wt_int(claim.get("balance"), 0, WT_MAX_BALANCE, WT_START_BALANCE)
            st = claim.get("stats") if isinstance(claim.get("stats"), dict) else {}
            won = _wt_int(st.get("won"), 0, 10 ** 12, 0)
            lost = _wt_int(st.get("lost"), 0, 10 ** 12, 0)
            day = st.get("day") if isinstance(st.get("day"), dict) else {}
            if str(day.get("date")) == wt_today():
                dd, da, dg = wt_today(), _wt_int(day.get("amount"), 0, 10 ** 12, 0), str(day.get("game") or "")[:20]
        conn.execute("INSERT INTO wt_users (user_id,first_name,last_name,username,balance,won,lost,day_date,day_amount,day_game,created_at,last_seen)"
                     " VALUES (?,?,?,?,?,?,?,?,?,?,?,?)", (tg["id"], first, last, uname, bal, won, lost, dd, da, dg, now, now))
    else:
        conn.execute("UPDATE wt_users SET first_name=?, last_name=?, username=?, last_seen=? WHERE user_id=?",
                     (first, last, uname, now, tg["id"]))
    return conn.execute("SELECT * FROM wt_users WHERE user_id=?", (tg["id"],)).fetchone()

def _wt_state(row):
    today = wt_today()
    same = row["day_date"] == today
    return {
        "id": row["user_id"], "balance": row["balance"], "is_admin": row["user_id"] in ADMIN_ID,
        "stats": {"won": row["won"], "lost": row["lost"],
                  "day": {"date": today, "amount": row["day_amount"] if same else 0, "game": row["day_game"] if same else ""}},
    }

def _wt_apply_delta(conn, uid, balance, base, dev="", seq=None):
    """Клиент присылает свой баланс и тот, от которого он считал. Применяем только разницу —
    так возвраты/покупки/выплаты игр, сделанные на сервере, не затираются.
    dev+seq защищают от двойного начисления: если ответ на запрос потерялся и клиент повторил его,
    повторно применяется только то, что накопилось после предыдущей попытки."""
    row = conn.execute("SELECT balance, sync_dev, sync_seq, sync_bal FROM wt_users WHERE user_id=?", (uid,)).fetchone()
    cur = row["balance"]
    if balance is None or base is None:
        return cur
    b = _wt_int(balance, 0, 10 ** 12, 0)
    bs = _wt_int(base, 0, 10 ** 12, 0)
    sq = _wt_int(seq, -1, 10 ** 12, -1) if seq is not None else -1
    if dev and sq >= 0 and row["sync_dev"] == dev and row["sync_seq"] == sq:
        delta = b - row["sync_bal"]
    else:
        delta = b - bs
    new = max(0, min(WT_MAX_BALANCE, cur + delta))
    conn.execute("UPDATE wt_users SET balance=?, sync_dev=?, sync_seq=?, sync_bal=? WHERE user_id=?", (new, dev, sq, b, uid))
    return new

def _wt_apply_body(conn, uid, body):
    return _wt_apply_delta(conn, uid, body.get("balance"), body.get("base"), str(body.get("dev") or "")[:40], body.get("seq"))

def _wt_merge_stats(conn, row, st):
    if not isinstance(st, dict):
        return
    won = max(row["won"], _wt_int(st.get("won"), 0, 10 ** 12, 0))
    lost = max(row["lost"], _wt_int(st.get("lost"), 0, 10 ** 12, 0))
    today = wt_today()
    dd, da, dg = row["day_date"], row["day_amount"], row["day_game"]
    if dd != today:
        dd, da, dg = today, 0, ""
    day = st.get("day") if isinstance(st.get("day"), dict) else {}
    if str(day.get("date")) == today:
        amt = _wt_int(day.get("amount"), 0, 10 ** 12, 0)
        if amt > da:
            da, dg = amt, str(day.get("game") or "")[:20]
    conn.execute("UPDATE wt_users SET won=?, lost=?, day_date=?, day_amount=?, day_game=? WHERE user_id=?",
                 (won, lost, dd, da, dg, row["user_id"]))

def _wt_user_epoch(conn, uid):
    """Эпоха сброса для клиента: общая (сброс бота) + личная (обнуление одного аккаунта админом)."""
    g = wt_get_setting(conn, "reset_epoch", "0")
    u = wt_get_setting(conn, f"user_reset_{uid}", "")
    return f"{g}.{u}" if u else g

def wt_api_me(tg, body):
    try:
        add_user(tg["id"])
    except Exception:
        pass
    with wt_tx() as conn:
        local = (body or {}).get("local")
        row = _wt_ensure_user(conn, tg, local)
        now = int(time.time())
        if row["bonus_at"] == 0 and isinstance(local, dict):
            ts = _wt_int(local.get("bonus_at"), 0, now, 0)
            try:
                reset_at = max(int(wt_get_setting(conn, "reset_epoch", "0")),
                               int(wt_get_setting(conn, f"user_reset_{tg['id']}", "0") or 0))
            except ValueError:
                reset_at = 0
            if ts > 0 and ts > reset_at:
                conn.execute("UPDATE wt_users SET bonus_at=?, bonus_notified=? WHERE user_id=?",
                             (ts, 1 if ts + WT_BONUS_COOLDOWN <= now else 0, tg["id"]))
        st = _wt_state(row)
        st["bonus_at"] = conn.execute("SELECT bonus_at FROM wt_users WHERE user_id=?", (tg["id"],)).fetchone()["bonus_at"]
        st["terms"] = conn.execute("SELECT 1 FROM wt_terms WHERE user_id=?", (tg["id"],)).fetchone() is not None
        st["epoch"] = _wt_user_epoch(conn, tg["id"])
        return st

def wt_api_terms_accept(tg, body):
    with wt_tx() as conn:
        _wt_ensure_user(conn, tg)
        conn.execute("INSERT OR IGNORE INTO wt_terms (user_id, accepted_at) VALUES (?,?)", (tg["id"], int(time.time())))
    return {"ok": True}

def wt_api_sync(tg, body):
    with wt_tx() as conn:
        row = _wt_ensure_user(conn, tg)
        epoch = _wt_user_epoch(conn, tg["id"])
        if str(body.get("epoch") or "0") != epoch:
            return {"balance": row["balance"], "reset": True, "epoch": epoch}
        _wt_merge_stats(conn, row, body.get("stats"))
        bal = _wt_apply_body(conn, tg["id"], body)
        row = conn.execute("SELECT * FROM wt_users WHERE user_id=?", (tg["id"],)).fetchone()
        return {"balance": bal, "stats": _wt_state(row)["stats"]}

def wt_api_top():
    conn = _wt_conn()
    try:
        def pack(rows, game=False):
            return [{"id": r["user_id"], "name": wt_name(r), "value": r["v"], **({"game": r["g"]} if game else {})} for r in rows]
        base = "SELECT user_id, first_name, last_name, username, {c} AS v, {g} AS g FROM wt_users WHERE {w} ORDER BY {c} DESC LIMIT {n}"
        won = conn.execute(base.format(c="won", g="''", w="won>0", n=10)).fetchall()
        lost = conn.execute(base.format(c="lost", g="''", w="lost>0", n=10)).fetchall()
        day = conn.execute(base.format(c="day_amount", g="day_game", w="day_date=? AND day_amount>0", n=5), (wt_today(),)).fetchall()
        return {"won": pack(won), "lost": pack(lost), "day": pack(day, True)}
    finally:
        conn.close()

def wt_get_setting(conn, key, default=""):
    r = conn.execute("SELECT value FROM wt_settings WHERE key=?", (key,)).fetchone()
    return r["value"] if r else default

def wt_set_setting(conn, key, value):
    conn.execute("INSERT OR REPLACE INTO wt_settings (key, value) VALUES (?,?)", (key, str(value)))

def wt_limit_days(conn):
    """Прежний общий лимит (нужен только как значение по умолчанию при миграции)."""
    try:
        v = int(wt_get_setting(conn, "shop_limit", "7"))
    except ValueError:
        v = 7
    return max(-1, min(30, v))

def wt_product_limit(prod, conn=None):
    """Лимит конкретного товара: -1 — один раз за всё время, 0 — без лимита, 1..30 — раз в N дней."""
    v = prod["limit_days"]
    if v is None:
        return wt_limit_days(conn) if conn is not None else 0
    return max(-1, min(30, int(v)))

def wt_limit_state(conn, uid, pid, days, now):
    """Лимит считается ТОЛЬКО по заказам этого товара. -> (forever, next_at)."""
    if days == 0:
        return False, 0
    last = conn.execute("SELECT created_at FROM wt_orders WHERE user_id=? AND product_id=? AND status IN ('new','done') "
                        "ORDER BY created_at DESC LIMIT 1", (uid, pid)).fetchone()
    if days == -1:
        return last is not None, 0
    nxt = (last["created_at"] + days * 86400) if last else 0
    return False, (nxt if nxt > now else 0)

def wt_api_admin_product_limit(tg, body):
    _wt_require_admin(tg)
    try:
        v = int(body.get("value"))
    except (TypeError, ValueError):
        raise WtError(400, "Некорректное значение")
    if v < -1 or v > 30:
        raise WtError(400, "Допустимо: -1 (один раз), 0 (без лимита), 1–30 дней")
    pid = _wt_int(body.get("id"), 1, 10 ** 9, 0)
    with wt_tx() as conn:
        cur = conn.execute("UPDATE wt_products SET limit_days=? WHERE id=? AND active=1", (v, pid))
        if cur.rowcount != 1:
            raise WtError(404, "Товар не найден")
    return {"ok": True, "limit": v}

def wt_api_shop(tg):
    now = int(time.time())
    conn = _wt_conn()
    try:
        rows = conn.execute("SELECT id,title,descr,price,stock,image,anim,is_prize,created_at,limit_days FROM wt_products WHERE active=1").fetchall()
        products = []
        for r in rows:
            days = wt_product_limit(r, conn)
            forever, nxt = wt_limit_state(conn, tg["id"], r["id"], days, now)
            products.append({
                "id": r["id"], "title": r["title"], "desc": r["descr"], "price": r["price"], "stock": r["stock"],
                "prize": bool(r["is_prize"]),
                "image": f"/api/product-image/{r['id']}?v={r['created_at']}" if r["image"] else "",
                "anim": f"/api/product-anim/{r['id']}?v={r['created_at']}" if r["anim"] else "",
                "limit": days, "forever": forever, "next_at": nxt,
            })
        return {"products": products}
    finally:
        conn.close()

def wt_api_buy(tg, body):
    pid = _wt_int(body.get("product_id"), 1, 10 ** 9, 0)
    comment = str(body.get("comment") or "").strip()[:300]
    if not re.search(r"@[A-Za-z0-9_]{4,32}", comment):
        raise WtError(400, "Укажите ваш @username в комментарии")
    now = int(time.time())
    with wt_tx() as conn:
        _wt_ensure_user(conn, tg)
        bal = _wt_apply_body(conn, tg["id"], body)
        prod = conn.execute("SELECT * FROM wt_products WHERE id=? AND active=1", (pid,)).fetchone()
        if not prod:
            raise WtError(404, "Товар не найден")
        days = wt_product_limit(prod, conn)
        forever, nxt = wt_limit_state(conn, tg["id"], pid, days, now)
        if forever:
            raise WtError(400, "Лимит на этот товар исчерпан: его можно получить только один раз")
        if nxt:
            raise WtError(400, f"Лимит на этот товар: 1 раз в {days} дн. Снова можно: " + wt_fmt_ts(nxt))
        if prod["stock"] < 1:
            raise WtError(400, "Нет в наличии")
        if bal < prod["price"]:
            raise WtError(400, "Недостаточно Слив")
        cur = conn.execute("UPDATE wt_products SET stock=stock-1 WHERE id=? AND stock>0", (pid,))
        if cur.rowcount != 1:
            raise WtError(400, "Нет в наличии")
        bal -= prod["price"]
        conn.execute("UPDATE wt_users SET balance=? WHERE user_id=?", (bal, tg["id"]))
        oid = conn.execute("INSERT INTO wt_orders (user_id,product_id,title,price,comment,status,created_at) VALUES (?,?,?,?,?,'new',?)",
                           (tg["id"], pid, prod["title"], prod["price"], comment, now)).lastrowid
    _wt_threading.Thread(target=wt_notify_admins, args=(oid,), daemon=True).start()
    return {"balance": bal, "order_id": oid}

def _wt_require_admin(tg):
    if tg["id"] not in ADMIN_ID:
        raise WtError(403, "Нет доступа")

def wt_api_admin_product(tg, body):
    _wt_require_admin(tg)
    title = str(body.get("title") or "").strip()[:80]
    descr = str(body.get("desc") or "").strip()[:300]
    price = _wt_int(body.get("price"), 0, 10 ** 8, 0)
    stock = _wt_int(body.get("stock"), 0, 10 ** 6, -1)
    limit = _wt_int(body.get("limit"), -1, 30, 7)
    image = str(body.get("image") or "")
    if not title or price < 1:
        raise WtError(400, "Укажите название и цену")
    if stock < 0:
        raise WtError(400, "Укажите наличие")
    if image and (not image.startswith("data:image/") or len(image) > 2_500_000):
        raise WtError(400, "Некорректное фото")
    with wt_tx() as conn:
        conn.execute("INSERT INTO wt_products (title,descr,price,stock,image,is_prize,active,created_at,limit_days) VALUES (?,?,?,?,?,0,1,?,?)",
                     (title, descr, price, stock, image, int(time.time()), limit))
    return {"ok": True}

def wt_api_admin_delete(tg, body):
    _wt_require_admin(tg)
    with wt_tx() as conn:
        conn.execute("UPDATE wt_products SET active=0 WHERE id=?", (_wt_int(body.get("id"), 1, 10 ** 9, 0),))
    return {"ok": True}

def wt_api_admin_stock(tg, body):
    _wt_require_admin(tg)
    with wt_tx() as conn:
        conn.execute("UPDATE wt_products SET stock=? WHERE id=? AND active=1",
                     (_wt_int(body.get("stock"), 0, 10 ** 6, 0), _wt_int(body.get("id"), 1, 10 ** 9, 0)))
    return {"ok": True}

def wt_bonus_claim_core(conn, uid, now):
    row = conn.execute("SELECT balance, bonus_at FROM wt_users WHERE user_id=?", (uid,)).fetchone()
    if row is None:
        raise WtError(404, "Пользователь не найден")
    if row["bonus_at"] and row["bonus_at"] + WT_BONUS_COOLDOWN > now:
        raise WtError(400, "Бонус ещё недоступен")
    bal = min(WT_MAX_BALANCE, row["balance"] + WT_BONUS_AMOUNT)
    conn.execute("UPDATE wt_users SET balance=?, bonus_at=?, bonus_notified=0 WHERE user_id=?", (bal, now, uid))
    return bal

def wt_api_bonus_claim(tg, body):
    now = int(time.time())
    with wt_tx() as conn:
        _wt_ensure_user(conn, tg)
        _wt_apply_body(conn, tg["id"], body)
        bal = wt_bonus_claim_core(conn, tg["id"], now)
    return {"balance": bal, "bonus_at": now, "amount": WT_BONUS_AMOUNT}

def wt_bonus_claim_from_button(uid, epoch):
    """-> ('ok', balance) | ('wait', None) | ('stale', None) | ('none', None)"""
    now = int(time.time())
    try:
        with wt_tx() as conn:
            if wt_get_setting(conn, "reset_epoch", "0") != epoch:
                return "stale", None
            return "ok", wt_bonus_claim_core(conn, uid, now)
    except WtError as e:
        return ("none" if e.code == 404 else "wait"), None

def wt_bonus_keyboard(epoch):
    return {"inline_keyboard": [[{"text": f"🎁 Забрать +{WT_BONUS_AMOUNT} Слив", "callback_data": f"wtbonus_{epoch}"}]]}

def wt_bonus_notify_due():
    """Каждому, кто забрал бонус и у кого он снова доступен, — одно уведомление. Следующее придёт только после нового «Забрать»."""
    now = int(time.time())
    with wt_tx() as conn:
        ids = [r["user_id"] for r in conn.execute(
            "SELECT user_id FROM wt_users WHERE bonus_at>0 AND bonus_notified=0 AND bonus_at<=?", (now - WT_BONUS_COOLDOWN,)).fetchall()]
        epoch = wt_get_setting(conn, "reset_epoch", "0")
        conn.executemany("UPDATE wt_users SET bonus_notified=1 WHERE user_id=?", [(i,) for i in ids])
    for uid in ids:
        wt_bot_api("sendMessage", {"chat_id": uid, "reply_markup": wt_bonus_keyboard(epoch),
                                   "text": f"🎁 Ежедневный бонус снова доступен!\nЗабирай +{WT_BONUS_AMOUNT} Слив."})
        time.sleep(0.05)

def wt_bonus_loop():
    time.sleep(20)
    while True:
        try:
            wt_bonus_notify_due()
        except Exception:
            logger.exception("Ежедневный бонус: ошибка рассылки уведомлений")
        time.sleep(60)

async def wt_bonus_callback(update, context):
    from telegram.ext import ApplicationHandlerStop
    q = update.callback_query
    m = re.match(r"^wtbonus_(\d+)$", q.data or "")
    if not m:
        raise ApplicationHandlerStop
    status, bal = await asyncio.to_thread(wt_bonus_claim_from_button, q.from_user.id, m.group(1))
    if status == "ok":
        text = (f"🎁 Бонус получен: +{WT_BONUS_AMOUNT} Слив!\nБаланс: {bal}\n"
                f"Следующий бонус будет доступен через {WT_BONUS_COOLDOWN // 3600} ч.")
        await q.answer(f"+{WT_BONUS_AMOUNT} Слив!")
    else:
        text = "🎁 Этот бонус уже получен или недоступен."
        await q.answer("Бонус уже получен" if status == "wait" else "Кнопка устарела", show_alert=True)
    try:
        await q.edit_message_text(text, reply_markup=None)
    except Exception:
        pass
    raise ApplicationHandlerStop

def wt_multipart_document(chat_id, filename, data, caption):
    boundary = "----wt" + _wt_hashlib.md5(os.urandom(16)).hexdigest()
    parts = []
    for k, v in (("chat_id", str(chat_id)), ("caption", caption)):
        parts.append(f'--{boundary}\r\nContent-Disposition: form-data; name="{k}"\r\n\r\n{v}\r\n'.encode("utf-8"))
    parts.append((f'--{boundary}\r\nContent-Disposition: form-data; name="document"; filename="{filename}"\r\n'
                  f'Content-Type: application/json\r\n\r\n').encode("utf-8") + data + b"\r\n")
    parts.append(f"--{boundary}--\r\n".encode())
    req = _wt_urlreq.Request(f"https://api.telegram.org/bot{TOKEN}/sendDocument", data=b"".join(parts),
                             headers={"Content-Type": f"multipart/form-data; boundary={boundary}"})
    with _wt_urlreq.urlopen(req, timeout=60) as resp:
        return json.loads(resp.read().decode("utf-8"))

def wt_send_backup(path, filename, summary, by, head=None):
    """Резервная копия уходит только администраторам (ADMIN_ID), обычным пользователям — никогда."""
    try:
        with open(path, "rb") as f:
            data = f.read()
    except Exception as e:
        logger.error("Сброс Mini App: не удалось прочитать резервную копию: %s", e)
        return
    caption = (f"♻️ {head or 'Mini App сброшен администратором ' + str(by)}.\n{summary}\n\n"
               "Это резервная копия данных до сброса (JSON).")
    for aid in ADMIN_ID:
        try:
            res = wt_multipart_document(aid, filename, data, caption)
            if not res.get("ok"):
                logger.warning("Резервная копия -> %s: %s", aid, res)
        except Exception as e:
            logger.warning("Резервная копия -> %s: %s", aid, e)

def wt_api_admin_reset(tg, body):
    """Полный сброс Mini App: Сливы -> 500, статистика, топы, заказы магазина/лимиты, задания, ежедневные бонусы.
    Товары, баннер, список заданий и соглашения не трогаем. Другие данные бота не затрагиваются."""
    _wt_require_admin(tg)
    if body.get("confirm") != "RESET":
        raise WtError(400, "Нужно подтверждение")
    now = int(time.time())
    stamp = datetime.fromtimestamp(now, WT_MSK).strftime("%Y%m%d_%H%M%S")
    filename = f"wt_miniapp_backup_{stamp}.json"
    folder = os.path.join(BASE_DIR, "backups")
    os.makedirs(folder, exist_ok=True)
    path = os.path.join(folder, filename)
    with wt_tx() as conn:
        def dump(sql):
            return [dict(r) for r in conn.execute(sql).fetchall()]
        data = {
            "created_at": now, "created_msk": datetime.fromtimestamp(now, WT_MSK).strftime("%Y-%m-%d %H:%M:%S МСК"),
            "by_admin": tg["id"], "start_balance": WT_START_BALANCE,
            "wt_users": dump("SELECT * FROM wt_users"),
            "wt_orders": dump("SELECT * FROM wt_orders"),
            "wt_task_done": dump("SELECT * FROM wt_task_done"),
            "wt_bonus_done": dump("SELECT * FROM wt_bonus_done"),
            "wt_products": dump("SELECT id,title,descr,price,stock,is_prize,active,created_at,limit_days FROM wt_products"),
        }
        with open(path, "w", encoding="utf-8") as f:
            json.dump(data, f, ensure_ascii=False, indent=1)
        n_users = len(data["wt_users"])
        n_orders = len(data["wt_orders"])
        conn.execute("UPDATE wt_users SET balance=?, won=0, lost=0, day_date='', day_amount=0, day_game='', bonus_at=0, bonus_notified=0, sync_dev='', sync_seq=-1, sync_bal=0", (WT_START_BALANCE,))
        conn.execute("DELETE FROM wt_bets")
        conn.execute("DELETE FROM wt_orders")
        conn.execute("DELETE FROM wt_task_done")
        conn.execute("DELETE FROM wt_bonus_done")
        wt_set_setting(conn, "reset_epoch", now)
    summary = f"Игроков: {n_users}, заказов в магазине: {n_orders}. Баланс всех возвращён к {WT_START_BALANCE} Слив."
    by = tg.get("first_name") or str(tg["id"])
    _wt_threading.Thread(target=wt_send_backup, args=(path, filename, summary, by), daemon=True).start()
    return {"ok": True, "users": n_users, "orders": n_orders}

def wt_api_admin_user_reset(tg, body):
    """Обнуляет аккаунт ОДНОГО игрока Mini App по Telegram ID: Сливы -> стартовые, статистика, ставки, заказы,
    выполненные задания и ежедневный бонус. Остальные игроки и данные бота не затрагиваются.
    Перед обнулением данные игрока уходят админам файлом (JSON)."""
    _wt_require_admin(tg)
    uid = _wt_int(body.get("user_id"), 0, 10 ** 15, 0)
    if uid < 1:
        raise WtError(400, "Укажи числовой Telegram ID")
    if body.get("confirm") != "RESET_USER":
        raise WtError(400, "Нужно подтверждение")
    now = int(time.time())
    stamp = datetime.fromtimestamp(now, WT_MSK).strftime("%Y%m%d_%H%M%S")
    filename = f"wt_user_{uid}_backup_{stamp}.json"
    folder = os.path.join(BASE_DIR, "backups")
    os.makedirs(folder, exist_ok=True)
    path = os.path.join(folder, filename)
    with wt_tx() as conn:
        row = conn.execute("SELECT * FROM wt_users WHERE user_id=?", (uid,)).fetchone()
        if row is None:
            raise WtError(404, "Такого игрока нет в Mini App")
        def dump(sql):
            return [dict(r) for r in conn.execute(sql, (uid,)).fetchall()]
        data = {
            "created_at": now, "created_msk": datetime.fromtimestamp(now, WT_MSK).strftime("%Y-%m-%d %H:%M:%S МСК"),
            "by_admin": tg["id"], "user_id": uid, "start_balance": WT_START_BALANCE,
            "wt_users": [dict(row)],
            "wt_orders": dump("SELECT * FROM wt_orders WHERE user_id=?"),
            "wt_task_done": dump("SELECT * FROM wt_task_done WHERE user_id=?"),
            "wt_bonus_done": dump("SELECT * FROM wt_bonus_done WHERE user_id=?"),
            "wt_bets": dump("SELECT * FROM wt_bets WHERE user_id=?"),
        }
        with open(path, "w", encoding="utf-8") as f:
            json.dump(data, f, ensure_ascii=False, indent=1)
        name = wt_name(row)
        old_balance = row["balance"]
        conn.execute("UPDATE wt_users SET balance=?, won=0, lost=0, day_date='', day_amount=0, day_game='', bonus_at=0, "
                     "bonus_notified=0, sync_dev='', sync_seq=-1, sync_bal=0 WHERE user_id=?", (WT_START_BALANCE, uid))
        conn.execute("DELETE FROM wt_bets WHERE user_id=?", (uid,))
        conn.execute("DELETE FROM wt_orders WHERE user_id=?", (uid,))
        conn.execute("DELETE FROM wt_task_done WHERE user_id=?", (uid,))
        conn.execute("DELETE FROM wt_bonus_done WHERE user_id=?", (uid,))
        wt_set_setting(conn, f"user_reset_{uid}", now)
    summary = (f"Игрок: {name} (ID {uid}). Было: {old_balance} Слив, заказов: {len(data['wt_orders'])}. "
               f"Баланс возвращён к {WT_START_BALANCE} Слив.")
    by = tg.get("first_name") or str(tg["id"])
    _wt_threading.Thread(target=wt_send_backup, args=(path, filename, summary, by, f"Аккаунт игрока {uid} обнулён администратором {by}"),
                         daemon=True).start()
    return {"ok": True, "name": name, "user_id": uid, "balance": WT_START_BALANCE}

def wt_api_banner():
    conn = _wt_conn()
    try:
        url = wt_get_setting(conn, "banner_url", "")
        v = wt_get_setting(conn, "banner_v", "0")
        has_img = bool(wt_get_setting(conn, "banner_image", ""))
    finally:
        conn.close()
    return {"url": url, "image": f"/api/banner-image?v={v}" if has_img else ""}

def wt_api_admin_banner(tg, body):
    _wt_require_admin(tg)
    with wt_tx() as conn:
        if body.get("clear"):
            for k in ("banner_url", "banner_image"):
                wt_set_setting(conn, k, "")
            wt_set_setting(conn, "banner_v", int(time.time()))
            return {"ok": True}
        url = str(body.get("url") or "").strip()[:300]
        if url and not re.match(r"^https?://", url, re.I):
            raise WtError(400, "Ссылка должна начинаться с https://")
        image = str(body.get("image") or "")
        if image:
            if not image.startswith("data:image/") or len(image) > 3_500_000:
                raise WtError(400, "Некорректное изображение")
            wt_set_setting(conn, "banner_image", image)
        wt_set_setting(conn, "banner_url", url)
        wt_set_setting(conn, "banner_v", int(time.time()))
    return {"ok": True}

_WT_TASK_LINK = re.compile(r"^(?:https?://)?(?:t\.me|telegram\.me)/([A-Za-z][A-Za-z0-9_]{3,31})/?(?:\?.*)?$", re.I)
_wt_bot_id = None

def wt_task_chat(link):
    link = str(link or "").strip()
    m = _WT_TASK_LINK.match(link) or re.match(r"^@([A-Za-z][A-Za-z0-9_]{3,31})$", link)
    if not m:
        raise WtError(400, "Нужна ссылка на публичный канал или чат вида https://t.me/wT2x2_Chat (приватные ссылки-приглашения проверить нельзя)")
    return m.group(1)

def wt_get_bot_id():
    global _wt_bot_id
    if _wt_bot_id is None:
        r = wt_bot_api("getMe")
        if r and r.get("ok"):
            _wt_bot_id = r["result"]["id"]
    return _wt_bot_id

def wt_api_tasks(tg):
    conn = _wt_conn()
    try:
        rows = conn.execute("SELECT id,title,reward,link FROM wt_tasks WHERE active=1 ORDER BY id").fetchall()
        done = {r["task_id"] for r in conn.execute("SELECT task_id FROM wt_task_done WHERE user_id=?", (tg["id"],)).fetchall()}
        return {"tasks": [{"id": r["id"], "title": r["title"], "reward": r["reward"], "link": r["link"], "done": r["id"] in done} for r in rows]}
    finally:
        conn.close()

def wt_api_admin_task(tg, body):
    _wt_require_admin(tg)
    title = str(body.get("title") or "").strip()[:80]
    reward = _wt_int(body.get("reward"), 0, 10 ** 7, 0)
    chat = wt_task_chat(body.get("link"))
    if not title or reward < 1:
        raise WtError(400, "Укажите название и награду")
    info = wt_bot_api("getChat", {"chat_id": "@" + chat})
    if not info or not info.get("ok"):
        raise WtError(400, "Бот не видит этот канал/чат. Проверьте ссылку и добавьте бота в канал/чат администратором")
    warning = ""
    bot_id = wt_get_bot_id()
    me = wt_bot_api("getChatMember", {"chat_id": "@" + chat, "user_id": bot_id}) if bot_id else None
    if not me or not me.get("ok") or me["result"].get("status") not in ("administrator", "creator"):
        warning = "Задание добавлено, но бот не администратор — без этого проверка подписок может не работать"
    with wt_tx() as conn:
        conn.execute("INSERT INTO wt_tasks (title,reward,link,chat,active,created_at) VALUES (?,?,?,?,1,?)",
                     (title, reward, f"https://t.me/{chat}", chat, int(time.time())))
    return {"ok": True, "warning": warning}

def wt_api_admin_task_delete(tg, body):
    _wt_require_admin(tg)
    with wt_tx() as conn:
        conn.execute("UPDATE wt_tasks SET active=0 WHERE id=?", (_wt_int(body.get("id"), 1, 10 ** 9, 0),))
    return {"ok": True}

def wt_api_task_claim(tg, body):
    tid = _wt_int(body.get("id"), 1, 10 ** 9, 0)
    conn = _wt_conn()
    try:
        task = conn.execute("SELECT * FROM wt_tasks WHERE id=? AND active=1", (tid,)).fetchone()
        if not task:
            raise WtError(404, "Задание не найдено")
        if conn.execute("SELECT 1 FROM wt_task_done WHERE user_id=? AND task_id=?", (tg["id"], tid)).fetchone():
            raise WtError(400, "Награда уже получена")
    finally:
        conn.close()
    res = wt_bot_api("getChatMember", {"chat_id": "@" + task["chat"], "user_id": tg["id"]})
    if not res or not res.get("ok"):
        logger.warning("Проверка подписки @%s: %s", task["chat"], res)
        raise WtError(400, "Не удалось проверить подписку. Сообщите администратору: бот должен быть админом канала/чата")
    m = res["result"]
    if not (m.get("status") in ("creator", "administrator", "member") or (m.get("status") == "restricted" and m.get("is_member"))):
        raise WtError(400, "Вы ещё не подписаны — подпишитесь и нажмите «Забрать награду» снова")
    with wt_tx() as conn:
        _wt_ensure_user(conn, tg)
        bal = _wt_apply_body(conn, tg["id"], body)
        try:
            conn.execute("INSERT INTO wt_task_done (user_id,task_id,reward,created_at) VALUES (?,?,?,?)",
                         (tg["id"], tid, task["reward"], int(time.time())))
        except sqlite3.IntegrityError:
            raise WtError(400, "Награда уже получена")
        bal = min(WT_MAX_BALANCE, bal + task["reward"])
        conn.execute("UPDATE wt_users SET balance=? WHERE user_id=?", (bal, tg["id"]))
    return {"balance": bal, "reward": task["reward"]}

def wt_http_get(url, timeout=20, limit=3_000_000):
    req = _wt_urlreq.Request(url, headers={"User-Agent": "Mozilla/5.0 (wT2x2 miniapp)"})
    with _wt_urlreq.urlopen(req, timeout=timeout) as resp:
        data = resp.read(limit + 1)
    if len(data) > limit:
        raise ValueError("слишком большой файл")
    return data

def wt_api_admin_prize(tg, body):
    """Главный приз: по ссылке на NFT-подарок (t.me/nft/Имя-123) берём анимацию и картинку с nft.fragment.com."""
    _wt_require_admin(tg)
    link = str(body.get("link") or "").strip()
    m = re.search(r"t\.me/nft/([A-Za-z0-9_]+)-(\d+)", link)
    if not m:
        raise WtError(400, "Нужна ссылка вида https://t.me/nft/PlushPepe-1234")
    name, number = m.group(1), m.group(2)
    slug = f"{name}-{number}".lower()
    price = _wt_int(body.get("price"), 0, 10 ** 8, 0)
    if price < 1:
        raise WtError(400, "Укажите цену")
    try:
        anim_bytes = wt_http_get(f"https://nft.fragment.com/gift/{slug}.lottie.json")
        anim_json = json.loads(anim_bytes.decode("utf-8"))
        if not isinstance(anim_json, dict) or "layers" not in anim_json:
            raise ValueError("не lottie")
    except Exception as e:
        logger.warning("NFT-подарок %s: не удалось получить анимацию: %s", slug, e)
        raise WtError(400, "Не удалось получить анимацию подарка — проверьте ссылку")
    image = ""
    for suffix in ("large.jpg", "medium.jpg"):
        try:
            image = "data:image/jpeg;base64," + base64.b64encode(wt_http_get(f"https://nft.fragment.com/gift/{slug}.{suffix}")).decode()
            break
        except Exception:
            continue
    title = str(body.get("title") or "").strip()[:80] or (re.sub(r"(?<!^)(?=[A-Z])", " ", name) + f" #{number}")
    with wt_tx() as conn:
        conn.execute("UPDATE wt_products SET active=0 WHERE is_prize=1 AND active=1")
        conn.execute("INSERT INTO wt_products (title,descr,price,stock,image,anim,is_prize,active,created_at,limit_days) VALUES (?,?,?,?,?,?,1,1,?,0)",
                     (title, "NFT-подарок Telegram", price, 1, image, json.dumps(anim_json, separators=(",", ":")), int(time.time())))
    return {"ok": True}

def wt_bot_api(method, payload=None, timeout=15):
    try:
        req = _wt_urlreq.Request(f"https://api.telegram.org/bot{TOKEN}/{method}",
                                 data=json.dumps(payload or {}).encode("utf-8"),
                                 headers={"Content-Type": "application/json"})
        with _wt_urlreq.urlopen(req, timeout=timeout) as resp:
            return json.loads(resp.read().decode("utf-8"))
    except Exception as e:
        logger.warning("Telegram API %s: %s", method, e)
        return None

def wt_order_text(order, user, status_line=""):
    uname = f" (@{_wt_html.escape(user['username'])})" if user["username"] else ""
    text = (f"🛒 <b>Запрос на покупку #{order['id']}</b>\n\n"
            f"Товар: <b>{_wt_html.escape(order['title'] or '')}</b>\n"
            f"Цена: {order['price']} Слив\n"
            f"Покупатель: <a href=\"tg://user?id={user['user_id']}\">{_wt_html.escape(wt_name(user))}</a>{uname}\n"
            f"ID: <code>{user['user_id']}</code>\n"
            f"Комментарий: {_wt_html.escape(order['comment'] or '—')}\n"
            f"Дата: {wt_fmt_ts(order['created_at'])}")
    return text + (f"\n\n{status_line}" if status_line else "")

def wt_order_keyboard(oid):
    return {"inline_keyboard": [[
        {"text": "✅ Выполнен", "callback_data": f"wtord_done_{oid}"},
        {"text": "↩️ Возврат", "callback_data": f"wtord_ref_{oid}"},
    ]]}

def wt_notify_admins(oid):
    conn = _wt_conn()
    try:
        order = conn.execute("SELECT * FROM wt_orders WHERE id=?", (oid,)).fetchone()
        user = conn.execute("SELECT * FROM wt_users WHERE user_id=?", (order["user_id"],)).fetchone()
    finally:
        conn.close()
    msgs = []
    for aid in ADMIN_ID:
        res = wt_bot_api("sendMessage", {"chat_id": aid, "text": wt_order_text(order, user), "parse_mode": "HTML",
                                         "disable_web_page_preview": True, "reply_markup": wt_order_keyboard(oid)})
        if res and res.get("ok"):
            msgs.append([aid, res["result"]["message_id"]])
    with wt_tx() as conn:
        conn.execute("UPDATE wt_orders SET msgs=? WHERE id=?", (json.dumps(msgs), oid))

def wt_close_order(oid, action, admin_id):
    """action: 'done' | 'ref'. Возвращает данные заказа или None, если заказ уже обработан."""
    with wt_tx() as conn:
        order = conn.execute("SELECT * FROM wt_orders WHERE id=?", (oid,)).fetchone()
        if not order or order["status"] != "new":
            return None
        status = "done" if action == "done" else "refunded"
        conn.execute("UPDATE wt_orders SET status=?, closed_at=?, closed_by=? WHERE id=?", (status, int(time.time()), admin_id, oid))
        if status == "refunded":
            conn.execute("UPDATE wt_users SET balance=MIN(?, balance+?) WHERE user_id=?", (WT_MAX_BALANCE, order["price"], order["user_id"]))
            if order["product_id"]:
                conn.execute("UPDATE wt_products SET stock=stock+1 WHERE id=?", (order["product_id"],))
        user = conn.execute("SELECT * FROM wt_users WHERE user_id=?", (order["user_id"],)).fetchone()
        order = conn.execute("SELECT * FROM wt_orders WHERE id=?", (oid,)).fetchone()
    return {"order": order, "user": user, "status": status}

async def wt_order_callback(update, context):
    from telegram.ext import ApplicationHandlerStop
    q = update.callback_query
    if q.from_user.id not in ADMIN_ID:
        await q.answer("Только для администраторов", show_alert=True)
        raise ApplicationHandlerStop
    m = re.match(r"^wtord_(done|ref)_(\d+)$", q.data or "")
    if not m:
        raise ApplicationHandlerStop
    action, oid = m.group(1), int(m.group(2))
    res = await asyncio.to_thread(wt_close_order, oid, action, q.from_user.id)
    if res is None:
        await q.answer("Заказ уже обработан", show_alert=True)
        try:
            await q.edit_message_reply_markup(reply_markup=None)
        except Exception:
            pass
        raise ApplicationHandlerStop
    order, user = res["order"], res["user"]
    who = _wt_html.escape(q.from_user.full_name or str(q.from_user.id))
    line = (f"✅ <b>Выполнен</b> — {who}" if res["status"] == "done" else f"↩️ <b>Возврат {order['price']} Слив</b> — {who}")
    text = wt_order_text(order, user, line)
    try:
        msgs = json.loads(order["msgs"] or "[]")
    except ValueError:
        msgs = []
    if not msgs:
        msgs = [[q.message.chat_id, q.message.message_id]]
    for chat_id, message_id in msgs:
        try:
            await context.bot.edit_message_text(chat_id=chat_id, message_id=message_id, text=text, parse_mode="HTML",
                                                disable_web_page_preview=True, reply_markup=None)
        except Exception:
            pass
    try:
        if res["status"] == "done":
            await context.bot.send_message(user["user_id"], f"✅ Ваш заказ «{order['title']}» выполнен. Спасибо!")
        else:
            await context.bot.send_message(user["user_id"], f"↩️ По заказу «{order['title']}» оформлен возврат: {order['price']} Слив возвращены на ваш баланс.")
    except Exception:
        pass
    await q.answer("Готово")
    raise ApplicationHandlerStop

_wt_avatar_cache = {}

def wt_avatar(uid):
    now = time.time()
    hit = _wt_avatar_cache.get(uid)
    if hit and now - hit[0] < (6 * 3600 if hit[1] else 600):
        return hit[1]
    data = None
    try:
        r = wt_bot_api("getUserProfilePhotos", {"user_id": uid, "limit": 1})
        photos = (r or {}).get("result", {}).get("photos") or []
        if photos:
            sizes = photos[0]
            file_id = sizes[min(1, len(sizes) - 1)]["file_id"]
            f = wt_bot_api("getFile", {"file_id": file_id})
            path = (f or {}).get("result", {}).get("file_path")
            if path:
                data = wt_http_get(f"https://api.telegram.org/file/bot{TOKEN}/{path}", limit=2_000_000)
    except Exception as e:
        logger.warning("Аватар %s: %s", uid, e)
    _wt_avatar_cache[uid] = (now, data)
    return data

WT_CRASH_BET_MS = 12000
WT_CRASH_RESULT_MS = 3000
WT_CRASH_ZERO_CHANCE = 0.05
WT_CRASH_ZERO_POINT = 1.00
WT_CRASH_INSTA_CHANCE = 0.10
WT_CRASH_INSTA_POINT = 1.01
WT_CRASH_LOW_CHANCE = 0.15
WT_CRASH_LOW_POINT = 1.05
WT_CRASH_MAX_LAG_MS = 1500
WT_TIMED_MS = 15000
WT_TIMED_CUTOFF_MS = 1500
WT_COIN_SIDES = ("heads", "tails", "edge")
WT_GAME_TITLES = {"crash": "Ракетка", "dice": "Кубик", "coin": "Монета", "upgrader": "Апгрейдер"}

WT_UPG_PRICES = [10, 12, 15, 18, 22, 27, 33, 40, 48, 58, 70, 85, 100, 120, 145, 175, 210, 250, 300, 360, 430, 520, 620, 750, 900, 1100, 1300, 1600, 1900, 2300, 2800, 3400, 4100, 4900, 5900, 7000, 8500, 10000, 12000, 14500, 18000, 22000, 27000, 33000, 41000, 50000, 61000, 74000, 87000, 100000]
WT_UPG_EDGE = 0.95
WT_UPG_MIN_CHANCE = 0.01
WT_UPG_MAX_CHANCE = 0.90
WT_UPG_BOOST_BASE = 0.97
WT_UPG_BOOST_SPAN = 0.45
_wt_secret_cache = None

def _wt_ms():
    return int(time.time() * 1000)

def _wt_games_secret(conn):
    global _wt_secret_cache
    if _wt_secret_cache is None:
        s = wt_get_setting(conn, "games_secret", "")
        if not s:
            conn.execute("INSERT OR IGNORE INTO wt_settings (key, value) VALUES ('games_secret', ?)", (_wt_secrets.token_hex(32),))
            s = wt_get_setting(conn, "games_secret", "")
        _wt_secret_cache = s
    return _wt_secret_cache

def _wt_rand_u(conn, tag):
    """Случайное число [0,1) из секрета сервера: клиент заранее результат узнать не может."""
    h = _wt_hmac.new(_wt_games_secret(conn).encode(), tag.encode(), _wt_hashlib.sha256).digest()
    return int.from_bytes(h[:8], "big") / 2.0 ** 64

def _wt_crash_mult(t):
    return 1 + 0.115 * t + 0.035 * t ** 1.55

def _wt_crash_time(point):
    lo, hi = 0.0, 600.0
    for _ in range(60):
        mid = (lo + hi) / 2
        if _wt_crash_mult(mid) < point:
            lo = mid
        else:
            hi = mid
    return hi

def _wt_timed_result(conn, game, rid):
    u = _wt_rand_u(conn, f"{game}:{rid}")
    if game == "dice":
        return str(1 + int(u * 6))
    return "heads" if u < 0.45 else "tails" if u < 0.9 else "edge"

def _wt_record(conn, uid, game, bet, payout):
    """Статистика игрока (выиграл/проиграл/лучшая ставка дня) — считается на сервере."""
    row = conn.execute("SELECT won, lost, day_date, day_amount, day_game FROM wt_users WHERE user_id=?", (uid,)).fetchone()
    if row is None:
        return
    won, lost = row["won"], row["lost"]
    if payout > bet:
        won += payout - bet
    elif payout < bet:
        lost += bet - payout
    today = wt_today()
    dd, da, dg = row["day_date"], row["day_amount"], row["day_game"]
    if dd != today:
        dd, da, dg = today, 0, ""
    if payout > da:
        da, dg = payout, game
    conn.execute("UPDATE wt_users SET won=?, lost=?, day_date=?, day_amount=?, day_game=? WHERE user_id=?",
                 (won, lost, dd, da, dg, uid))

def _wt_credit(conn, uid, amount):
    conn.execute("UPDATE wt_users SET balance=MIN(?, balance+?) WHERE user_id=?", (WT_MAX_BALANCE, amount, uid))

def _wt_debit(conn, uid, amount):
    """Списание ставки: только если хватает баланса (в одной операции — отрицательным баланс стать не может)."""
    cur = conn.execute("UPDATE wt_users SET balance=balance-? WHERE user_id=? AND balance>=?", (amount, uid, amount))
    if cur.rowcount != 1:
        raise WtError(400, "Недостаточно Слив")

def _wt_balance(conn, uid):
    return conn.execute("SELECT balance FROM wt_users WHERE user_id=?", (uid,)).fetchone()["balance"]

def _wt_players(conn, game, rid_from, limit=30):
    rows = conn.execute(
        "SELECT b.amount, b.choice, b.status, b.payout, b.mult, b.round_id, u.first_name, u.last_name, u.username "
        "FROM wt_bets b JOIN wt_users u ON u.user_id=b.user_id WHERE b.game=? AND b.round_id>=? "
        "ORDER BY b.amount DESC LIMIT ?", (game, rid_from, limit)).fetchall()
    return [{"name": wt_name(r), "bet": r["amount"], "choice": r["choice"], "status": r["status"],
             "payout": r["payout"], "mult": r["mult"], "round_id": r["round_id"]} for r in rows]

def _wt_crash_latest(conn):
    return conn.execute("SELECT * FROM wt_crash_rounds ORDER BY id DESC LIMIT 1").fetchone()

def _wt_crash_advance(conn, now):
    """Закрывает упавшие раунды (непроданные ставки сгорают) и открывает новый раунд. Вызывать внутри wt_tx."""
    r = _wt_crash_latest(conn)
    if r is not None and now >= r["crash_at"]:
        rows = conn.execute(
            "SELECT b.id, b.user_id, b.amount FROM wt_bets b JOIN wt_crash_rounds c ON c.id=b.round_id "
            "WHERE b.game='crash' AND b.status='open' AND c.crash_at<=?", (now,)).fetchall()
        for b in rows:
            if conn.execute("UPDATE wt_bets SET status='lost', payout=0 WHERE id=? AND status='open'", (b["id"],)).rowcount == 1:
                _wt_record(conn, b["user_id"], WT_GAME_TITLES["crash"], b["amount"], 0)
    if r is None or now >= r["crash_at"] + WT_CRASH_RESULT_MS:
        rid = (r["id"] + 1) if r else 1
        u0 = _wt_rand_u(conn, f"crash_insta:{rid}")
        if u0 < WT_CRASH_ZERO_CHANCE:
            point = WT_CRASH_ZERO_POINT
        elif u0 < WT_CRASH_ZERO_CHANCE + WT_CRASH_INSTA_CHANCE:
            point = WT_CRASH_INSTA_POINT
        elif u0 < WT_CRASH_ZERO_CHANCE + WT_CRASH_INSTA_CHANCE + WT_CRASH_LOW_CHANCE:
            point = WT_CRASH_LOW_POINT
        else:
            point = 1.08 + _wt_rand_u(conn, f"crash:{rid}") ** 1.6 * 2.7
        start = now + WT_CRASH_BET_MS
        crash_at = start + int(_wt_crash_time(point) * 1000)
        conn.execute("INSERT INTO wt_crash_rounds (id, start_at, crash_at, point) VALUES (?,?,?,?)", (rid, start, crash_at, point))
        old = now - 2 * 86400 * 1000
        conn.execute("DELETE FROM wt_bets WHERE status!='open' AND created_at<?", (old // 1000,))
        conn.execute("DELETE FROM wt_crash_rounds WHERE crash_at<? AND id<?", (old, rid))
        r = _wt_crash_latest(conn)
    return r

def _wt_crash_sync(now):
    conn = _wt_conn()
    try:
        r = _wt_crash_latest(conn)
        need = r is None or now >= r["crash_at"] + WT_CRASH_RESULT_MS
        if not need and now >= r["crash_at"]:
            need = conn.execute("SELECT 1 FROM wt_bets WHERE game='crash' AND round_id=? AND status='open' LIMIT 1",
                                (r["id"],)).fetchone() is not None
    finally:
        conn.close()
    if need:
        with wt_tx() as c:
            _wt_crash_advance(c, now)

def _wt_crash_state(conn, uid, now):
    r = _wt_crash_latest(conn)
    phase = "waiting" if now < r["start_at"] else "running" if now < r["crash_at"] else "ended"
    s = {"now": now, "id": r["id"], "phase": phase, "start_at": r["start_at"],
         "players": _wt_players(conn, "crash", r["id"])}
    if phase == "ended":
        s["point"] = r["point"]
        s["crash_at"] = r["crash_at"]
    m = conn.execute("SELECT amount, status, payout, mult FROM wt_bets WHERE game='crash' AND round_id=? AND user_id=?",
                     (r["id"], uid)).fetchone()
    s["mine"] = dict(m) if m else None
    row = conn.execute("SELECT * FROM wt_users WHERE user_id=?", (uid,)).fetchone()
    s["stats"] = _wt_state(row)["stats"] if row else None
    return s

def wt_api_crash_bet(tg, body):
    amount = _wt_int(body.get("amount"), 0, WT_MAX_BALANCE, 0)
    if amount < 1:
        raise WtError(400, "Укажи ставку")
    now = _wt_ms()
    uid = tg["id"]
    with wt_tx() as conn:
        _wt_ensure_user(conn, tg)
        _wt_apply_body(conn, uid, body)
        r = _wt_crash_advance(conn, now)
        if now >= r["start_at"]:
            raise WtError(400, "Раунд уже идёт — дождись следующего")
        if conn.execute("SELECT 1 FROM wt_bets WHERE game='crash' AND round_id=? AND user_id=?", (r["id"], uid)).fetchone():
            raise WtError(400, "Ставка уже принята на текущий раунд")
        _wt_debit(conn, uid, amount)
        conn.execute("INSERT INTO wt_bets (game, round_id, user_id, amount, created_at) VALUES ('crash',?,?,?,?)",
                     (r["id"], uid, amount, now // 1000))
        return {"balance": _wt_balance(conn, uid), "state": _wt_crash_state(conn, uid, now)}

def wt_api_crash_cash(tg, body):
    now = _wt_ms()
    uid = tg["id"]
    with wt_tx() as conn:
        _wt_ensure_user(conn, tg)
        _wt_apply_body(conn, uid, body)
        r = _wt_crash_advance(conn, now)
        b = conn.execute("SELECT * FROM wt_bets WHERE game='crash' AND round_id=? AND user_id=?", (r["id"], uid)).fetchone()
        if not b:
            raise WtError(400, "У тебя нет ставки в этом раунде")
        if b["status"] == "cashed":
            raise WtError(400, "Ставка уже забрана")
        if b["status"] != "open" or now >= r["crash_at"]:
            raise WtError(400, "Ракета уже упала — ставка сгорела")
        if now < r["start_at"]:
            raise WtError(400, "Раунд ещё не начался")
        elapsed = now - r["start_at"]
        use_ms = elapsed
        claim = body.get("t")
        if isinstance(claim, (int, float)) and not isinstance(claim, bool) and 0 <= claim <= elapsed:
            use_ms = max(claim, elapsed - WT_CRASH_MAX_LAG_MS)
        m = round(min(_wt_crash_mult(use_ms / 1000.0), r["point"]), 2)
        win = int(b["amount"] * m)
        if conn.execute("UPDATE wt_bets SET status='cashed', payout=?, mult=? WHERE id=? AND status='open'",
                        (win, m, b["id"])).rowcount != 1:
            raise WtError(400, "Ставка уже закрыта")
        _wt_credit(conn, uid, win)
        _wt_record(conn, uid, WT_GAME_TITLES["crash"], b["amount"], win)
        return {"balance": _wt_balance(conn, uid), "win": win, "mult": m, "state": _wt_crash_state(conn, uid, now)}

def _wt_timed_settle(conn, now):
    rid = now // WT_TIMED_MS
    rows = conn.execute("SELECT * FROM wt_bets WHERE game IN ('dice','coin') AND status='open' AND round_id<?", (rid,)).fetchall()
    for b in rows:
        res = _wt_timed_result(conn, b["game"], b["round_id"])
        win = 0
        if res == b["choice"]:
            win = b["amount"] * (5 if b["game"] == "dice" else 10 if res == "edge" else 2)
        if conn.execute("UPDATE wt_bets SET status=?, payout=?, result=? WHERE id=? AND status='open'",
                        ("won" if win else "lost", win, res, b["id"])).rowcount != 1:
            continue
        if win:
            _wt_credit(conn, b["user_id"], win)
        _wt_record(conn, b["user_id"], WT_GAME_TITLES[b["game"]], b["amount"], win)

def _wt_timed_sync(now):
    conn = _wt_conn()
    try:
        need = conn.execute("SELECT 1 FROM wt_bets WHERE game IN ('dice','coin') AND status='open' AND round_id<? LIMIT 1",
                            (now // WT_TIMED_MS,)).fetchone() is not None
    finally:
        conn.close()
    if need:
        with wt_tx() as c:
            _wt_timed_settle(c, now)

def _wt_timed_state(conn, game, uid, now):
    rid = now // WT_TIMED_MS
    s = {"now": now, "round_id": rid, "ends_at": (rid + 1) * WT_TIMED_MS, "resolved_at": rid * WT_TIMED_MS,
         "last": {"round_id": rid - 1, "result": _wt_timed_result(conn, game, rid - 1)},
         "players": [], "prev": []}
    for p in _wt_players(conn, game, rid - 1, 60):
        (s["players"] if p["round_id"] >= rid else s["prev"]).append(p)
    m = conn.execute("SELECT amount, choice FROM wt_bets WHERE game=? AND user_id=? AND status='open' AND round_id>=?",
                     (game, uid, rid)).fetchone()
    s["mine"] = dict(m) if m else None
    pm = conn.execute("SELECT round_id, amount, choice, status, payout FROM wt_bets WHERE game=? AND user_id=? AND status!='open' "
                      "ORDER BY round_id DESC LIMIT 1", (game, uid)).fetchone()
    s["prev_mine"] = dict(pm) if pm else None
    row = conn.execute("SELECT * FROM wt_users WHERE user_id=?", (uid,)).fetchone()
    s["stats"] = _wt_state(row)["stats"] if row else None
    return s

def wt_api_timed_bet(tg, game, body):
    amount = _wt_int(body.get("amount"), 0, WT_MAX_BALANCE, 0)
    if amount < 1:
        raise WtError(400, "Укажи ставку")
    choice = str(body.get("choice") or "")
    if game == "dice":
        if choice not in ("1", "2", "3", "4", "5", "6"):
            raise WtError(400, "Выбери число от 1 до 6")
    elif choice not in WT_COIN_SIDES:
        raise WtError(400, "Выбери сторону монеты")
    now = _wt_ms()
    uid = tg["id"]
    with wt_tx() as conn:
        _wt_ensure_user(conn, tg)
        _wt_apply_body(conn, uid, body)
        _wt_timed_settle(conn, now)
        if conn.execute("SELECT 1 FROM wt_bets WHERE game=? AND user_id=? AND status='open'", (game, uid)).fetchone():
            raise WtError(400, "Ставка уже принята на текущий раунд")
        _wt_debit(conn, uid, amount)
        conn.execute("INSERT INTO wt_bets (game, round_id, user_id, amount, choice, created_at) VALUES (?,?,?,?,?,?)",
                     (game, (now + WT_TIMED_CUTOFF_MS) // WT_TIMED_MS, uid, amount, choice, now // 1000))
        return {"balance": _wt_balance(conn, uid), "state": _wt_timed_state(conn, game, uid, now)}

def wt_api_upgrader_play(tg, body):
    """Апгрейдер: игрок «отдаёт» предмет `src` (его цена списывается с баланса) и пытается получить дорогой предмет `item`."""
    n = len(WT_UPG_PRICES)
    src = _wt_int(body.get("src"), -1, n - 1, -1)
    item = _wt_int(body.get("item"), -1, n - 1, -1)
    if src < 0:
        raise WtError(400, "Выбери предмет, который прокачиваешь")
    if item < 0:
        raise WtError(400, "Выбери предмет, который хочешь получить")
    amount, price = WT_UPG_PRICES[src], WT_UPG_PRICES[item]
    if price <= amount:
        raise WtError(400, "Выбери предмет дороже")
    disp = amount / price * WT_UPG_EDGE
    if disp < WT_UPG_MIN_CHANCE:
        raise WtError(400, "Слишком дорогой предмет для такого апгрейда (шанс меньше 1%)")
    if disp > WT_UPG_MAX_CHANCE:
        raise WtError(400, "Слишком дешёвый предмет для такого апгрейда (шанс больше 90%)")
    t = math.log(price / 10.0) / math.log(10000.0)
    real = min(0.95, disp * (WT_UPG_BOOST_BASE + WT_UPG_BOOST_SPAN * t))
    rnd = random.SystemRandom()
    win = rnd.random() < real
    pos = rnd.random() * disp if win else disp + rnd.random() * (1 - disp)
    uid = tg["id"]
    with wt_tx() as conn:
        _wt_ensure_user(conn, tg)
        _wt_apply_body(conn, uid, body)
        _wt_debit(conn, uid, amount)
        payout = price if win else 0
        if payout:
            _wt_credit(conn, uid, payout)
        _wt_record(conn, uid, WT_GAME_TITLES["upgrader"], amount, payout)
        return {"balance": _wt_balance(conn, uid), "win": win, "payout": payout, "bet": amount,
                "chance": round(disp * 100, 2), "pos": round(pos, 5), "item": item, "src": src}

def wt_api_bonuses(tg):
    conn = _wt_conn()
    try:
        rows = conn.execute("SELECT id,title,reward FROM wt_bonuses WHERE active=1 ORDER BY id").fetchall()
        done = {r["bonus_id"] for r in conn.execute("SELECT bonus_id FROM wt_bonus_done WHERE user_id=?", (tg["id"],)).fetchall()}
        return {"bonuses": [{"id": r["id"], "title": r["title"], "reward": r["reward"], "done": r["id"] in done} for r in rows]}
    finally:
        conn.close()

def wt_api_admin_bonus(tg, body):
    _wt_require_admin(tg)
    title = str(body.get("title") or "").strip()[:80]
    reward = _wt_int(body.get("reward"), 0, 10 ** 7, 0)
    if not title or reward < 1:
        raise WtError(400, "Укажите название и награду")
    with wt_tx() as conn:
        conn.execute("INSERT INTO wt_bonuses (title,reward,active,created_at) VALUES (?,?,1,?)", (title, reward, int(time.time())))
    return {"ok": True}

def wt_api_admin_bonus_delete(tg, body):
    _wt_require_admin(tg)
    with wt_tx() as conn:
        conn.execute("UPDATE wt_bonuses SET active=0 WHERE id=?", (_wt_int(body.get("id"), 1, 10 ** 9, 0),))
    return {"ok": True}

def wt_api_bonus_one_claim(tg, body):
    bid = _wt_int(body.get("id"), 1, 10 ** 9, 0)
    with wt_tx() as conn:
        _wt_ensure_user(conn, tg)
        bal = _wt_apply_body(conn, tg["id"], body)
        bonus = conn.execute("SELECT * FROM wt_bonuses WHERE id=? AND active=1", (bid,)).fetchone()
        if not bonus:
            raise WtError(404, "Бонус не найден")
        try:
            conn.execute("INSERT INTO wt_bonus_done (user_id,bonus_id,reward,created_at) VALUES (?,?,?,?)",
                         (tg["id"], bid, bonus["reward"], int(time.time())))
        except sqlite3.IntegrityError:
            raise WtError(400, "Бонус уже получен")
        bal = min(WT_MAX_BALANCE, bal + bonus["reward"])
        conn.execute("UPDATE wt_users SET balance=? WHERE user_id=?", (bal, tg["id"]))
    return {"balance": bal, "reward": bonus["reward"]}

def wt_api_game_state(tg, game):
    now = _wt_ms()
    if game == "crash":
        _wt_crash_sync(now)
    else:
        _wt_timed_sync(now)
    conn = _wt_conn()
    try:
        if game == "crash":
            return _wt_crash_state(conn, tg["id"], now)
        return _wt_timed_state(conn, game, tg["id"], now)
    finally:
        conn.close()

_wt_html_cache = None

def wt_html_bytes():
    global _wt_html_cache
    if os.path.exists(WEBAPP_OVERRIDE):
        with open(WEBAPP_OVERRIDE, "rb") as f:
            return f.read()
    if _wt_html_cache is None:
        _wt_html_cache = _wt_zlib.decompress(base64.b64decode(_WEBAPP_B64))
    return _wt_html_cache

def _wt_data_url(value):
    m = re.match(r"^data:([\w/+.-]+);base64,(.*)$", value or "", re.S)
    if not m:
        return None, None
    return m.group(1), base64.b64decode(m.group(2))

class WtHandler(_WtBaseHandler):
    protocol_version = "HTTP/1.1"
    server_version = "wT2x2"

    def log_message(self, *args):
        pass

    def _send(self, code, body, ctype, headers=None):
        if isinstance(body, str):
            body = body.encode("utf-8")
        self.send_response(code)
        self.send_header("Content-Type", ctype)
        self.send_header("Content-Length", str(len(body)))
        for k, v in (headers or {}).items():
            self.send_header(k, v)
        self.end_headers()
        if self.command != "HEAD":
            self.wfile.write(body)

    def _json(self, code, obj):
        self._send(code, json.dumps(obj, ensure_ascii=False), "application/json; charset=utf-8", {"Cache-Control": "no-store"})

    def _body(self):
        n = _wt_int(self.headers.get("Content-Length"), 0, 10 ** 10, 0)
        if n > WT_MAX_BODY:
            raise WtError(413, "Слишком большой запрос")
        raw = self.rfile.read(n) if n else b""
        try:
            data = json.loads(raw.decode("utf-8") or "{}")
        except ValueError:
            raise WtError(400, "Некорректный JSON")
        return data if isinstance(data, dict) else {}

    def do_GET(self):
        self._route("GET")

    def do_HEAD(self):
        self._route("GET")

    def do_POST(self):
        self._route("POST")

    def _tg(self):
        return wt_parse_init_data(self.headers.get("X-Telegram-Init-Data", ""))

    def _route(self, method):
        try:
            path = _wt_urlparse.urlparse(self.path).path.rstrip("/") or "/"
            if method == "GET":
                if path in ("/", "/app", "/index.html"):
                    return self._send(200, wt_html_bytes(), "text/html; charset=utf-8", {"Cache-Control": "no-store"})
                if path == "/healthz":
                    return self._send(200, "ok", "text/plain")
                m = re.match(r"^/api/avatar/(\d+)$", path)
                if m:
                    uid = int(m.group(1))
                    conn = _wt_conn()
                    try:
                        known = conn.execute("SELECT 1 FROM wt_users WHERE user_id=?", (uid,)).fetchone()
                    finally:
                        conn.close()
                    data = wt_avatar(uid) if known else None
                    if not data:
                        return self._send(404, "", "text/plain")
                    return self._send(200, data, "image/jpeg", {"Cache-Control": "public, max-age=3600"})
                m = re.match(r"^/api/product-(image|anim)/(\d+)$", path)
                if m:
                    conn = _wt_conn()
                    try:
                        r = conn.execute("SELECT image, anim FROM wt_products WHERE id=?", (int(m.group(2)),)).fetchone()
                    finally:
                        conn.close()
                    if not r:
                        return self._send(404, "", "text/plain")
                    if m.group(1) == "anim":
                        if not r["anim"]:
                            return self._send(404, "", "text/plain")
                        return self._send(200, r["anim"], "application/json", {"Cache-Control": "public, max-age=86400"})
                    mime, data = _wt_data_url(r["image"])
                    if not data:
                        return self._send(404, "", "text/plain")
                    return self._send(200, data, mime, {"Cache-Control": "public, max-age=86400"})
                if path == "/api/top":
                    self._tg()
                    return self._json(200, wt_api_top())
                if path == "/api/shop":
                    return self._json(200, wt_api_shop(self._tg()))
                if path == "/api/banner":
                    self._tg()
                    return self._json(200, wt_api_banner())
                if path == "/api/banner-image":
                    conn = _wt_conn()
                    try:
                        img = wt_get_setting(conn, "banner_image", "")
                    finally:
                        conn.close()
                    mime, data = _wt_data_url(img)
                    if not data:
                        return self._send(404, "", "text/plain")
                    return self._send(200, data, mime, {"Cache-Control": "public, max-age=31536000, immutable"})
                if path == "/api/tasks":
                    return self._json(200, wt_api_tasks(self._tg()))
                if path == "/api/bonuses":
                    return self._json(200, wt_api_bonuses(self._tg()))
                m = re.match(r"^/api/game/(crash|dice|coin)/state$", path)
                if m:
                    return self._json(200, wt_api_game_state(self._tg(), m.group(1)))
                raise WtError(404, "Не найдено")
            tg = self._tg()
            body = self._body()
            routes = {
                "/api/me": lambda: wt_api_me(tg, body),
                "/api/sync": lambda: wt_api_sync(tg, body),
                "/api/shop/buy": lambda: wt_api_buy(tg, body),
                "/api/admin/product": lambda: wt_api_admin_product(tg, body),
                "/api/admin/product/delete": lambda: wt_api_admin_delete(tg, body),
                "/api/admin/product/stock": lambda: wt_api_admin_stock(tg, body),
                "/api/admin/prize": lambda: wt_api_admin_prize(tg, body),
                "/api/terms/accept": lambda: wt_api_terms_accept(tg, body),
                "/api/tasks/claim": lambda: wt_api_task_claim(tg, body),
                "/api/bonuses/claim": lambda: wt_api_bonus_one_claim(tg, body),
                "/api/admin/bonus": lambda: wt_api_admin_bonus(tg, body),
                "/api/admin/bonus/delete": lambda: wt_api_admin_bonus_delete(tg, body),
                "/api/admin/banner": lambda: wt_api_admin_banner(tg, body),
                "/api/admin/product/limit": lambda: wt_api_admin_product_limit(tg, body),
                "/api/admin/reset": lambda: wt_api_admin_reset(tg, body),
                "/api/admin/user/reset": lambda: wt_api_admin_user_reset(tg, body),
                "/api/bonus/claim": lambda: wt_api_bonus_claim(tg, body),
                "/api/game/crash/bet": lambda: wt_api_crash_bet(tg, body),
                "/api/game/crash/cash": lambda: wt_api_crash_cash(tg, body),
                "/api/game/dice/bet": lambda: wt_api_timed_bet(tg, "dice", body),
                "/api/game/coin/bet": lambda: wt_api_timed_bet(tg, "coin", body),
                "/api/game/upgrader/play": lambda: wt_api_upgrader_play(tg, body),
                "/api/admin/task": lambda: wt_api_admin_task(tg, body),
                "/api/admin/task/delete": lambda: wt_api_admin_task_delete(tg, body),
            }
            if path not in routes:
                raise WtError(404, "Не найдено")
            return self._json(200, routes[path]())
        except WtError as e:
            self._json(e.code, {"error": e.msg})
        except Exception:
            logger.exception("Ошибка Mini App API")
            self._json(500, {"error": "Ошибка сервера"})

def wt_start_web():
    try:
        wt_init_db()
        srv = _WtServer((WEB_HOST, WEB_PORT), WtHandler)
        srv.daemon_threads = True
        _wt_threading.Thread(target=srv.serve_forever, daemon=True, name="wt-web").start()
        _wt_threading.Thread(target=wt_bonus_loop, daemon=True, name="wt-bonus").start()
        logger.info("Mini App: слушаю %s:%s, адрес %s", WEB_HOST, WEB_PORT, WEBAPP_URL)
        return srv
    except Exception as e:
        logger.error("Mini App: веб-сервер не запустился: %s", e)
        return None

def wt_setup_web():
    """python3 wt2x2_bot.py --setup-web  — nginx + HTTPS для домена Mini App (нужен root)."""
    import subprocess
    if hasattr(os, "geteuid") and os.geteuid() != 0:
        print("Запустите от root:  sudo python3 wt2x2_bot.py --setup-web")
        return
    conf = (
        "server {\n"
        "    listen 80;\n"
        f"    server_name {WEBAPP_DOMAIN} www.{WEBAPP_DOMAIN};\n"
        "    client_max_body_size 8m;\n"
        "    location / {\n"
        f"        proxy_pass http://127.0.0.1:{WEB_PORT};\n"
        "        proxy_set_header Host $host;\n"
        "        proxy_set_header X-Real-IP $remote_addr;\n"
        "        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;\n"
        "        proxy_set_header X-Forwarded-Proto $scheme;\n"
        "    }\n"
        "}\n"
    )
    avail = f"/etc/nginx/sites-available/{WEBAPP_DOMAIN}"
    enabled = f"/etc/nginx/sites-enabled/{WEBAPP_DOMAIN}"
    with open(avail, "w", encoding="utf-8") as f:
        f.write(conf)
    if not os.path.exists(enabled):
        os.symlink(avail, enabled)
    subprocess.run(["nginx", "-t"], check=True)
    subprocess.run(["systemctl", "reload", "nginx"], check=True)
    print(f"✓ nginx настроен для {WEBAPP_DOMAIN} -> 127.0.0.1:{WEB_PORT}")
    print(f"Убедитесь, что у домена A-запись на IP этого сервера. Выпускаю HTTPS-сертификат…")
    email = input("E-mail для Let's Encrypt (Enter — без e-mail): ").strip()
    cmd = ["certbot", "--nginx", "-d", WEBAPP_DOMAIN, "-d", f"www.{WEBAPP_DOMAIN}", "--non-interactive", "--agree-tos", "--redirect"]
    cmd += ["-m", email] if email else ["--register-unsafely-without-email"]
    subprocess.run(cmd, check=False)
    print(f"Готово: {WEBAPP_URL}")

async def _post_init(application):
    try:
        await application.bot.set_chat_menu_button(
            menu_button=MenuButtonWebApp(text="Открыть Mini App", web_app=WebAppInfo(url=WEBAPP_URL)))
    except Exception as e:
        logger.warning("Не удалось установить кнопку меню Mini App: %s", e)
    await moderator.set_me(application)
    job_queue = application.job_queue
    if job_queue:
        job_queue.run_repeating(clear_webhook_job, interval=86400, first=60)

def main():
    init_db()
    wt_start_web()
    application = Application.builder().token(TOKEN).post_init(_post_init).build()
    moderator.register(application)
    application.add_handler(CallbackQueryHandler(wt_order_callback, pattern=r"^wtord_"), group=-1)
    application.add_handler(CallbackQueryHandler(wt_bonus_callback, pattern=r"^wtbonus_"), group=-1)
    application.add_error_handler(moderator.on_error)
    flow_switch = CallbackQueryHandler(universal_flow_switch, pattern=FLOW_SWITCH_PATTERN)
    input_flows = ConversationHandler(
        entry_points=[
            CallbackQueryHandler(autoreply_set_start, pattern="^admin_set_autoreply$"),
            CallbackQueryHandler(set_limit_start, pattern="^admin_set_limit$"),
            CallbackQueryHandler(image_set_start, pattern="^admin_set_image$"),
            CallbackQueryHandler(admin_reply_start, pattern="^reply_"),
            CallbackQueryHandler(broadcast_start, pattern="^admin_broadcast$"),
            CallbackQueryHandler(add_full_start, pattern="^admin_add_full$"),
            CallbackQueryHandler(admin_edit_full_start, pattern="^admin_edit_full_"),
            CallbackQueryHandler(get_full_start, pattern="^full$"),
            CallbackQueryHandler(suggest_start, pattern="^suggest$"),
            CallbackQueryHandler(donate_crypto_start, pattern="^cryptopay$"),
            CallbackQueryHandler(donate_stars_start, pattern="^donate_stars$"),
        ],
        states={
            ADMIN_SET_AUTOREPLY_WAIT: [MessageHandler(filters.ALL & ~filters.COMMAND, autoreply_set_process)],
            ADMIN_SET_LIMIT_WAIT: [MessageHandler(filters.TEXT & ~filters.COMMAND, set_limit_process)],
            ADMIN_SET_IMAGE_WAIT: [MessageHandler(filters.PHOTO | filters.TEXT & ~filters.COMMAND, image_set_process)],
            ADMIN_REPLY_WAIT: [MessageHandler(filters.ALL & ~filters.COMMAND, admin_reply_send)],
            BROADCAST_MSG: [MessageHandler(filters.ALL & ~filters.COMMAND, broadcast_send)],
            FULL_CODE_ADD: [MessageHandler(filters.TEXT & ~filters.COMMAND, add_full_code)],
            FULL_MEDIA_ADD: [MessageHandler(filters.ALL & ~filters.COMMAND, add_full_media)],
            FULL_CODE_GET: [MessageHandler(filters.TEXT & ~filters.COMMAND, get_full_send)],
            SUGGEST_WAIT_INPUT: [MessageHandler(filters.ALL & ~filters.COMMAND, suggest_receive)],
            DONATE_AMOUNT_WAIT: [MessageHandler(filters.TEXT & ~filters.COMMAND, donate_crypto_process)],
            STARS_AMOUNT_WAIT: [
                CallbackQueryHandler(stars_amount_chosen, pattern="^stars_amt_"),
                CallbackQueryHandler(stars_custom_start, pattern="^stars_custom$"),
            ],
            STARS_CUSTOM_WAIT: [MessageHandler(filters.TEXT & ~filters.COMMAND, stars_custom_process)],
        },
        fallbacks=[
            CommandHandler("cancel", cancel),
            CallbackQueryHandler(admin_cancel_callback, pattern="^admin_cancel$"),
            CallbackQueryHandler(cancel_full_callback, pattern="^cancel_full$"),
            CallbackQueryHandler(cancel_suggest_callback, pattern="^cancel_suggest$"),
            CallbackQueryHandler(cancel_donate_callback, pattern="^cancel_donate$"),
            flow_switch,
        ],
    )
    application.add_handlers([
        CommandHandler("start", start),
        CommandHandler("admin", admin_cmd),
        CommandHandler("donate", donate_cmd),
        CallbackQueryHandler(admin_stats_callback, pattern="^admin_stats$"),
        CallbackQueryHandler(fulls_manage_list, pattern="^admin_fulls_manage$"),
        CallbackQueryHandler(fulladmin_menu, pattern="^fulladmin_"),
        CallbackQueryHandler(admin_del_full_callback, pattern="^admin_del_full_"),
        CallbackQueryHandler(cryptocheck_callback, pattern="^cryptocheck_"),
        PreCheckoutQueryHandler(precheckout_callback),
        MessageHandler(filters.SUCCESSFUL_PAYMENT, successful_payment_callback),
        MessageHandler(STARS_MSG_FILTER & ~filters.COMMAND, stars_message_receive),
        MessageHandler((filters.ChatType.GROUPS | filters.ChatType.SUPERGROUP) & ~filters.COMMAND, chat_auto_reply),
        MessageHandler(filters.StatusUpdate.PINNED_MESSAGE, handle_pinned_service_message),
        input_flows,
        CallbackQueryHandler(obrabotka)
    ])
    print("🤖 Бот запущен!")
    application.run_polling(drop_pending_updates=True)

